    56→  specialPoopSpeedReduction(type: 'gold' | 'diamond'): number;
    57→
    58→  /** true → 일반 똥 스폰 완전 차단 */
    59→  isSpawnBlocked(): boolean;
    60→  /** 다음 소환 시 줄일 똥 개수 반환 후 0으로 리셋 (노이즈 특수 능력) */
    61→  getSpawnCountReduction(): number;
