import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 레거시 (UR)
 * - 기본 효과: 게임 시작 시 6초간 금똥 2개씩 내려오는 피버타임 + 황금 빗줄기(D)
 *             + 똥 스폰마다 20% 확률로 랜덤 2개 화염 추적선(B) + 불태워 소멸 (+10점)
 *             + 캐릭터 주변 상시 불꽃 오라(A)
 * - 특수 능력: 500점마다 레거시 모드 10초 발동
 *             — 점수 1.2배 + 화면 전체 불꽃 폭발 + 황금 실루엣(C) + 테두리 글로우
 *             — 불태우기 강화: 40% 확률로 4개 소멸 / 오라 황금빛으로 강화
 */
export class LegacyAbility extends BaseAbility {
  private startFeverActive = false;
  private legacyModeActive = false;
  private accum           = 0;
  private lastLegacyScore = 0;
  private legacyGlow?:       Phaser.GameObjects.Graphics; // 캐릭터 주변 노란 글로우
  private legacyTopGlow?:    Phaser.GameObjects.Graphics;
  private legacyPulseTween?: Phaser.Tweens.Tween;

  // A: 상시 불꽃 오라 — delta 누산 타이머
  private oraTimer = 0;
  private static readonly ORA_INTERVAL_NORMAL = 220; // ms
  private static readonly ORA_INTERVAL_LEGACY = 110; // ms (레거시 모드 중 더 빠름)

  // SSJ 오라 — 주기적 redraw로 일렁임 구현
  private auraGfx?: Phaser.GameObjects.Graphics;
  private auraRedrawTimer = 0;
  private static readonly AURA_REDRAW_MS = 80; // ms마다 스파이크 모양 재생성

  // ── 불꽃 물방울 다각형 좌표 (static 공유) ──────────────────────────
  private static flamePts(w: number, h: number) {
    return [
      { x:  0,         y: -h        },
      { x:  w * 0.55,  y: -h * 0.1  },
      { x:  w * 0.75,  y:  h * 0.35 },
      { x:  w * 0.3,   y:  h        },
      { x: -w * 0.3,   y:  h        },
      { x: -w * 0.75,  y:  h * 0.35 },
      { x: -w * 0.55,  y: -h * 0.1  },
    ];
  }

  // ─────────────────────────────────────────────────────────────────
  // 생명주기
  // ─────────────────────────────────────────────────────────────────

  override onCreate(api: GameSceneAPI): void {
    this.startFeverActive = true;
    this.startFeverRain(api);                    // D: 황금 빗줄기 시작
    api.scene.time.delayedCall(6000, () => {
      this.startFeverActive = false;
    });

    // SSJ 오라 Graphics 미리 생성 (매 80ms clear+redraw)
    this.auraGfx = api.scene.add.graphics().setDepth(85);
  }

  override onUpdate(api: GameSceneAPI): void {
    const delta = api.scene.game.loop.delta;

    // A: 불꽃 오라 — 일정 간격마다 파티클 1개 생성
    this.oraTimer += delta;
    const interval = this.legacyModeActive
      ? LegacyAbility.ORA_INTERVAL_LEGACY
      : LegacyAbility.ORA_INTERVAL_NORMAL;
    if (this.oraTimer >= interval) {
      this.oraTimer -= interval;
      this.spawnOraFlame(api);
    }

    // SSJ 오라 — 80ms마다 스파이크 재생성으로 일렁임 표현
    this.auraRedrawTimer += delta;
    if (this.auraRedrawTimer >= LegacyAbility.AURA_REDRAW_MS) {
      this.auraRedrawTimer -= LegacyAbility.AURA_REDRAW_MS;
      this.redrawAura(api);
    }

    // 캐릭터 글로우를 플레이어 위치에 맞게 갱신
    if (this.legacyGlow?.active) {
      this.legacyGlow.setPosition(api.player.x, api.player.y);
    }
  }

  override getTickScore(base: number): number {
    if (!this.legacyModeActive) return base;
    this.accum += base * 0.2;
    const bonus = Math.floor(this.accum);
    this.accum -= bonus;
    return base + bonus;
  }

  override overrideSpawnPoop(api: GameSceneAPI): boolean {
    if (this.startFeverActive) {
      api.spawnGoldPoop();
      api.spawnGoldPoop();
      return true;
    }
    return false;
  }

  override onAfterSpawnPoop(api: GameSceneAPI): void {
    const chance = this.legacyModeActive ? 0.4 : 0.2;
    const count  = this.legacyModeActive ? 4   : 2;
    if (Math.random() < chance) {
      this.burnRandomPoops(api, count);
    }
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % 500 === 0 && score > this.lastLegacyScore) {
      this.lastLegacyScore = score;
      this.activateLegacyMode(api);
    }
  }

  // ─────────────────────────────────────────────────────────────────
  // SSJ 오라 redraw
  // ─────────────────────────────────────────────────────────────────

  private redrawAura(api: GameSceneAPI): void {
    if (!this.auraGfx?.active) return;

    const gfx = this.auraGfx;
    const leg  = this.legacyModeActive;
    gfx.clear();
    gfx.setPosition(api.player.x, api.player.y);

    // 극좌표로 스파이크 24점 생성 (12 tip + 12 valley)
    const NUM_SPIKES = 12;
    const innerR     = leg ? 44 : 32;
    const spikeMin   = leg ? 28 : 16;
    const spikeMax   = leg ? 54 : 34;
    const VERT_RATIO = 1.45; // 세로 방향으로 늘려 불꽃 실루엣

    const pts: { x: number; y: number }[] = [];
    for (let i = 0; i < NUM_SPIKES * 2; i++) {
      // -π/2에서 시작 → 맨 위 꼭짓점부터 시계 방향
      const angle   = (i / (NUM_SPIKES * 2)) * Math.PI * 2 - Math.PI / 2;
      const isTip   = i % 2 === 0;

      // 위쪽 스파이크일수록 더 길게 (SSJ 왕관 효과)
      const upBonus = isTip ? Math.max(0, -Math.sin(angle)) * (leg ? 22 : 14) : 0;

      const r = isTip
        ? innerR + Phaser.Math.Between(spikeMin, spikeMax) + upBonus
        : innerR - Phaser.Math.Between(0, 10);

      pts.push({
        x: Math.cos(angle) * r,
        y: Math.sin(angle) * r * VERT_RATIO,
      });
    }

    // 외곽 → 중간 → 코어 3겹 (레거시 모드: 황금, 평상시: 붉은 오렌지)
    if (leg) {
      gfx.fillStyle(0xff8800, 0.10); gfx.fillPoints(pts, true);
      const mid  = pts.map(p => ({ x: p.x * 0.70, y: p.y * 0.70 }));
      gfx.fillStyle(0xffcc00, 0.20); gfx.fillPoints(mid, true);
      const core = pts.map(p => ({ x: p.x * 0.42, y: p.y * 0.42 }));
      gfx.fillStyle(0xffee88, 0.28); gfx.fillPoints(core, true);
    } else {
      gfx.fillStyle(0x991100, 0.07); gfx.fillPoints(pts, true);
      const mid  = pts.map(p => ({ x: p.x * 0.70, y: p.y * 0.70 }));
      gfx.fillStyle(0xff4400, 0.13); gfx.fillPoints(mid, true);
      const core = pts.map(p => ({ x: p.x * 0.42, y: p.y * 0.42 }));
      gfx.fillStyle(0xffaa00, 0.18); gfx.fillPoints(core, true);
    }
  }

  // ─────────────────────────────────────────────────────────────────
  // A: 상시 불꽃 오라
  // ─────────────────────────────────────────────────────────────────

  private spawnOraFlame(api: GameSceneAPI): void {
    const scene = api.scene;
    const px    = api.player.x;
    const py    = api.player.y;
    const leg   = this.legacyModeActive;

    const w = leg ? Phaser.Math.Between(5, 9)  : Phaser.Math.Between(3, 6);
    const h = leg ? Phaser.Math.Between(12, 20) : Phaser.Math.Between(8, 14);

    const gfx = scene.add.graphics();

    if (leg) {
      // 레거시 모드: 황금빛 오라
      gfx.fillStyle(0xcc5500, 0.20); gfx.fillPoints(LegacyAbility.flamePts(w,        h       ), true);
      gfx.fillStyle(0xff8800, 0.38); gfx.fillPoints(LegacyAbility.flamePts(w * 0.70, h * 0.76), true);
      gfx.fillStyle(0xffdd00, 0.56); gfx.fillPoints(LegacyAbility.flamePts(w * 0.40, h * 0.50), true);
    } else {
      // 평상시: 붉은 오렌지 오라
      gfx.fillStyle(0xaa1100, 0.16); gfx.fillPoints(LegacyAbility.flamePts(w,        h       ), true);
      gfx.fillStyle(0xff4400, 0.32); gfx.fillPoints(LegacyAbility.flamePts(w * 0.70, h * 0.76), true);
      gfx.fillStyle(0xffaa00, 0.46); gfx.fillPoints(LegacyAbility.flamePts(w * 0.40, h * 0.50), true);
    }

    gfx.setPosition(
      px + Phaser.Math.Between(-14, 14),
      py + Phaser.Math.Between(10, 26), // 발 근처에서 시작
    );
    gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(-20, 20)));
    gfx.setDepth(88); // 플레이어 뒤

    const life = leg ? Phaser.Math.Between(400, 700) : Phaser.Math.Between(280, 500);
    const rise = leg ? Phaser.Math.Between(30, 55)   : Phaser.Math.Between(18, 36);

    scene.tweens.add({
      targets:  gfx,
      y:        gfx.y - rise,
      alpha:    0,
      scaleX:   0.2,
      scaleY:   0.2,
      duration: life,
      ease:     'Quad.easeOut',
      onComplete: () => { gfx.destroy(); },
    });
  }

  // ─────────────────────────────────────────────────────────────────
  // B: 화염 추적선 (burn 이벤트 시 플레이어 → 소멸 위치)
  // ─────────────────────────────────────────────────────────────────

  private drawFireTrail(
    scene: Phaser.Scene,
    fromX: number, fromY: number,
    toList: { x: number; y: number }[],
  ): void {
    if (toList.length === 0) return;

    const gfx = scene.add.graphics();
    gfx.setDepth(195);

    for (const { x, y } of toList) {
      // 외곽: 두꺼운 오렌지 반투명
      gfx.lineStyle(3.5, 0xff6600, 0.50);
      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();

      // 내부: 얇은 노란 선
      gfx.lineStyle(1.5, 0xffee00, 0.75);
      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
    }

    scene.tweens.add({
      targets:  gfx,
      alpha:    0,
      duration: 200,
      ease:     'Quad.easeOut',
      onComplete: () => { gfx.destroy(); },
    });
  }

  // ─────────────────────────────────────────────────────────────────
  // C: 레거시 모드 활성화 — 폭발 연출 + 테두리 글로우
  // ─────────────────────────────────────────────────────────────────

  private activateLegacyMode(api: GameSceneAPI): void {
    if (this.legacyModeActive) return;
    this.legacyModeActive = true;
    this.accum = 0;

    const scene = api.scene;
    const cx    = api.player.x;
    const cy    = api.player.y;

    // ─ 이중 폭발 버스트 (1탄: 주황 → 2탄: 노랑, 화면 전체 커버) ────
    const playBurst = (
      color: number, flashR: number, flashG: number, flashB: number, burstDelay: number,
    ) => {
      scene.time.delayedCall(burstDelay, () => {
        scene.cameras.main.flash(150, flashR, flashG, flashB, true);

        // 팽창 링 2개 — maxScale 14로 화면 전체 커버 (반경 ~518px)
        [{ rDelay: 0, maxScale: 14 }, { rDelay: 80, maxScale: 11 }].forEach(({ rDelay, maxScale }) => {
          const ring = scene.add.graphics().setDepth(155);
          ring.lineStyle(2.5, color, 0.92);
          ring.strokeEllipse(0, 0, 74, 98);
          ring.setPosition(cx, cy);
          scene.tweens.add({
            targets: ring, scaleX: maxScale, scaleY: maxScale, alpha: 0,
            duration: 550, delay: rDelay, ease: 'Quad.easeOut',
            onComplete: () => { ring.destroy(); },
          });
        });

        // 채움 타원 (빠르게 사라짐)
        const fillGfx = scene.add.graphics().setDepth(154);
        fillGfx.fillStyle(color, 0.28);
        fillGfx.fillEllipse(0, 0, 74, 98);
        fillGfx.setPosition(cx, cy);
        scene.tweens.add({
          targets: fillGfx, alpha: 0, duration: 180, ease: 'Quad.easeOut',
          onComplete: () => { fillGfx.destroy(); },
        });

        // 파편 8개
        for (let i = 0; i < 8; i++) {
          const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
          const speed = Phaser.Math.FloatBetween(45, 100);
          const sw    = Phaser.Math.Between(5, 13);
          const sh    = Phaser.Math.Between(2, 5);
          const shard = scene.add.graphics().setDepth(156);
          shard.fillStyle(color, 1);
          shard.fillRect(-sw / 2, -sh / 2, sw, sh);
          shard.setPosition(cx, cy).setRotation(angle);
          scene.tweens.add({
            targets: shard,
            x: cx + Math.cos(angle) * speed,
            y: cy + Math.sin(angle) * speed,
            alpha: 0,
            rotation: angle + Phaser.Math.FloatBetween(-1, 1),
            duration: Phaser.Math.Between(280, 460), ease: 'Quad.easeOut',
            onComplete: () => { shard.destroy(); },
          });
        }
      });
    };

    playBurst(0xff8800, 255, 140,   0,   0); // 1탄: 주황
    playBurst(0xffee44, 255, 220,   0, 210); // 2탄: 노랑

    // ─ 황금 실루엣 (플레이어 주변 타원) ─────────────────────────
    const silhouette = scene.add.graphics();
    silhouette.fillStyle(0xffdd00, 0.50);
    silhouette.fillEllipse(0, 0, 88, 128);
    silhouette.setPosition(cx, cy).setDepth(157).setAlpha(0);
    scene.tweens.add({
      targets: silhouette, alpha: 1, scaleX: 1.25, scaleY: 1.25,
      duration: 110, ease: 'Quad.easeOut',
      onComplete: () => {
        scene.tweens.add({
          targets: silhouette, alpha: 0, scaleX: 1.8, scaleY: 1.8,
          duration: 300, ease: 'Quad.easeIn',
          onComplete: () => { silhouette.destroy(); },
        });
      },
    });

    // ─ 화면 전체 불꽃 폭발 (20개) ────────────────────────────────
    const BURST_COLS = [0xff2200, 0xff6600, 0xffaa00, 0xffdd00, 0xffff88];
    for (let i = 0; i < 20; i++) {
      const gfx = scene.add.graphics();
      const w   = Phaser.Math.Between(4, 10);
      const h   = Phaser.Math.Between(10, 22);
      const col = BURST_COLS[Math.floor(Math.random() * BURST_COLS.length)];

      gfx.fillStyle(col, Phaser.Math.FloatBetween(0.22, 0.50));
      gfx.fillPoints(LegacyAbility.flamePts(w, h), true);
      gfx.fillStyle(0xffee88, Phaser.Math.FloatBetween(0.28, 0.55));
      gfx.fillPoints(LegacyAbility.flamePts(w * 0.4, h * 0.5), true);

      gfx.setPosition(Phaser.Math.Between(20, 380), Phaser.Math.Between(40, 560));
      gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(-180, 180)));
      gfx.setDepth(158).setAlpha(0);

      const delay = Phaser.Math.Between(0, 280);
      scene.tweens.add({
        targets: gfx, alpha: 1,
        scaleX: Phaser.Math.FloatBetween(1.2, 1.9),
        scaleY: Phaser.Math.FloatBetween(1.2, 1.9),
        duration: 140, delay, ease: 'Quad.easeOut',
        onComplete: () => {
          scene.tweens.add({
            targets: gfx, alpha: 0, y: gfx.y - Phaser.Math.Between(20, 50),
            duration: Phaser.Math.Between(380, 650), ease: 'Quad.easeIn',
            onComplete: () => { gfx.destroy(); },
          });
        },
      });
    }

    // ─ 상단 노란빛 그라데이션 (위에서 아래로 퍼지는 빛) ─────────
    this.legacyTopGlow = scene.add.graphics();
    // fillGradientStyle: 상단 alpha 0.28 → 하단 alpha 0 (노란 빛이 위에서 내려오는 느낌)
    this.legacyTopGlow.fillGradientStyle(0xffee00, 0xffee00, 0xffee00, 0xffee00, 0.28, 0.28, 0, 0);
    this.legacyTopGlow.fillRect(0, 0, 400, 220);
    this.legacyTopGlow.setDepth(148);

    // ─ 캐릭터 노란 글로우 (동심 타원 4겹, 플레이어 추적) ──────────
    // 한 번 그리고 setPosition만 갱신 → 매 프레임 redraw 없음
    this.legacyGlow = scene.add.graphics();
    // 바깥부터 안쪽으로 점점 진해지는 노란 글로우
    this.legacyGlow.fillStyle(0xffee00, 0.08); this.legacyGlow.fillEllipse(0, 0, 110, 140);
    this.legacyGlow.fillStyle(0xffee00, 0.14); this.legacyGlow.fillEllipse(0, 0,  88, 114);
    this.legacyGlow.fillStyle(0xffee00, 0.22); this.legacyGlow.fillEllipse(0, 0,  70,  92);
    this.legacyGlow.fillStyle(0xffdd00, 0.32); this.legacyGlow.fillEllipse(0, 0,  56,  74);
    this.legacyGlow.setPosition(cx, cy).setDepth(87); // 플레이어 바로 뒤

    // 글로우 + 상단 빛 동시 펄스
    this.legacyPulseTween = scene.tweens.add({
      targets:  [this.legacyGlow, this.legacyTopGlow],
      alpha:    0.55,
      duration: 600, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
    });

    // 10초 후 종료
    scene.time.delayedCall(10000, () => {
      this.legacyModeActive = false;
      this.legacyPulseTween?.stop();
      this.legacyPulseTween = undefined;
      scene.tweens.add({
        targets: [this.legacyGlow, this.legacyTopGlow],
        alpha: 0, duration: 400, ease: 'Quad.easeOut',
        onComplete: () => {
          this.legacyGlow?.destroy();
          this.legacyGlow = undefined;
          this.legacyTopGlow?.destroy();
          this.legacyTopGlow = undefined;
        },
      });
    });
  }

  // ─────────────────────────────────────────────────────────────────
  // D: 황금 빗줄기 (피버타임 6초)
  // ─────────────────────────────────────────────────────────────────

  private startFeverRain(api: GameSceneAPI): void {
    const scene    = api.scene;
    const GOLD     = [0xffcc00, 0xffee44, 0xffd700, 0xffbb33];
    const REPEAT   = Math.floor(6000 / 140) - 1; // 6초 동안, 자동 종료

    scene.time.addEvent({
      delay:  140,
      repeat: REPEAT,
      callback: () => {
        for (let i = 0; i < 2; i++) {
          const gfx = scene.add.graphics();
          const s   = Phaser.Math.FloatBetween(2.5, 5.5);
          const col = GOLD[Math.floor(Math.random() * GOLD.length)];
          const a   = Phaser.Math.FloatBetween(0.30, 0.60);

          // 8각 별/다이아몬드
          gfx.fillStyle(col, a);
          gfx.fillPoints([
            { x:  0,       y: -s      }, { x:  s * 0.4,  y: -s * 0.4 },
            { x:  s,       y:  0      }, { x:  s * 0.4,  y:  s * 0.4 },
            { x:  0,       y:  s      }, { x: -s * 0.4,  y:  s * 0.4 },
            { x: -s,       y:  0      }, { x: -s * 0.4,  y: -s * 0.4 },
          ], true);

          // 중심 하이라이트
          gfx.fillStyle(0xffffff, 0.50);
          gfx.fillCircle(0, 0, s * 0.32);

          gfx.setPosition(Phaser.Math.Between(10, 390), -15);
          gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(0, 360)));
          gfx.setDepth(85);

          scene.tweens.add({
            targets:  gfx,
            y:        gfx.y + Phaser.Math.Between(450, 600),
            x:        gfx.x + Phaser.Math.Between(-25, 25),
            rotation: gfx.rotation + Phaser.Math.FloatBetween(1.5, 3.0),
            alpha:    0,
            duration: Phaser.Math.Between(2200, 3600),
            ease:     'Linear',
            onComplete: () => { gfx.destroy(); },
          });
        }
      },
    });
  }

  // ─────────────────────────────────────────────────────────────────
  // 불태우기 로직
  // ─────────────────────────────────────────────────────────────────

  private burnRandomPoops(api: GameSceneAPI, count: number): void {
    const visible = api.poops.getChildren().filter(
      c => c.active && (c as Phaser.Physics.Arcade.Sprite).y > -10,
    ) as Phaser.Physics.Arcade.Sprite[];

    if (visible.length === 0) return;

    // Fisher-Yates 셔플
    const pool = visible.slice();
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    const targets = pool.slice(0, Math.min(count, pool.length));

    // B: 화염 추적선 (플레이어 → 각 소멸 위치)
    this.drawFireTrail(
      api.scene,
      api.player.x, api.player.y,
      targets.map(p => ({ x: p.x, y: p.y })),
    );

    for (const poop of targets) {
      if (!poop.active) continue;
      this.playBurnEffect(api.scene, poop.x, poop.y);
      poop.destroy();
      api.updateScore(10);
    }
  }

  // ─────────────────────────────────────────────────────────────────
  // 불꽃 소멸 이펙트
  // ─────────────────────────────────────────────────────────────────

  private playBurnEffect(scene: Phaser.Scene, cx: number, cy: number): void {
    // ── 점화 flash ──────────────────────────────────────────────────
    const flash = scene.add.graphics();
    flash.fillStyle(0xff7700, 0.60); flash.fillCircle(0, 0, 17);
    flash.fillStyle(0xffee88, 0.45); flash.fillCircle(0, 0, 9);
    flash.setPosition(cx, cy).setDepth(202);
    scene.tweens.add({
      targets: flash, scaleX: 2.8, scaleY: 2.8, alpha: 0,
      duration: 190, ease: 'Quad.easeOut',
      onComplete: () => { flash.destroy(); },
    });

    // ── 불꽃 10개 (3-레이어) ────────────────────────────────────────
    for (let i = 0; i < 10; i++) {
      const gfx = scene.add.graphics();
      const w   = Phaser.Math.Between(5, 11);
      const h   = Phaser.Math.Between(14, 27);

      gfx.fillStyle(0xaa1100, 0.25); gfx.fillPoints(LegacyAbility.flamePts(w,        h       ), true);
      gfx.fillStyle(0xff4400, 0.48); gfx.fillPoints(LegacyAbility.flamePts(w * 0.70, h * 0.76), true);
      gfx.fillStyle(0xffcc00, 0.68); gfx.fillPoints(LegacyAbility.flamePts(w * 0.40, h * 0.50), true);

      gfx.setPosition(
        cx + Phaser.Math.Between(-15, 15),
        cy + Phaser.Math.Between(-10, 10),
      );
      gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(-28, 28)));
      gfx.setDepth(200);

      const rise = Phaser.Math.Between(48, 88);
      const dur  = Phaser.Math.Between(500, 900);

      scene.tweens.add({
        targets: gfx, y: gfx.y - rise * 0.38, scaleX: 1.45, scaleY: 1.45,
        duration: dur * 0.35, ease: 'Quad.easeOut',
        onComplete: () => {
          scene.tweens.add({
            targets: gfx, y: gfx.y - rise * 0.62, scaleX: 0, scaleY: 0, alpha: 0,
            duration: dur * 0.65, ease: 'Quad.easeIn',
            onComplete: () => { gfx.destroy(); },
          });
        },
      });
    }

    // ── 잔불 ember 8개 (다이아몬드 2-레이어) ────────────────────────
    const EMBER_COLS = [0xff5500, 0xff8800, 0xffbb00];
    for (let i = 0; i < 8; i++) {
      const gfx = scene.add.graphics();
      const s   = Phaser.Math.Between(2, 5);
      const col = EMBER_COLS[Math.floor(Math.random() * EMBER_COLS.length)];

      gfx.fillStyle(col, 0.18);
      gfx.fillPoints([{ x: 0, y: -s * 1.9 }, { x: s * 1.9, y: 0 }, { x: 0, y: s * 1.9 }, { x: -s * 1.9, y: 0 }], true);
      gfx.fillStyle(0xffee88, 0.65);
      gfx.fillPoints([{ x: 0, y: -s }, { x: s, y: 0 }, { x: 0, y: s }, { x: -s, y: 0 }], true);

      gfx.setPosition(
        cx + Phaser.Math.Between(-18, 18),
        cy + Phaser.Math.Between(-18, 18),
      ).setDepth(201);

      const rad  = Phaser.Math.DegToRad(Phaser.Math.Between(185, 355));
      const dist = Phaser.Math.Between(28, 65);

      scene.tweens.add({
        targets: gfx,
        x: gfx.x + Math.cos(rad) * dist,
        y: gfx.y + Math.sin(rad) * dist - Phaser.Math.Between(18, 40),
        rotation: Phaser.Math.DegToRad(Phaser.Math.Between(200, 400)),
        alpha: 0, scaleX: 0, scaleY: 0,
        duration: Phaser.Math.Between(650, 1050),
        delay:    Phaser.Math.Between(0, 220),
        ease:     'Sine.easeOut',
        onComplete: () => { gfx.destroy(); },
      });
    }

    // ── 연기 4개 ────────────────────────────────────────────────────
    for (let i = 0; i < 4; i++) {
      const gfx = scene.add.graphics();
      gfx.fillStyle(0x331100, 0.28);
      gfx.fillCircle(0, 0, Phaser.Math.Between(6, 13));
      gfx.setPosition(
        cx + Phaser.Math.Between(-12, 12),
        cy + Phaser.Math.Between(-10, 4),
      ).setDepth(199);

      scene.tweens.add({
        targets: gfx,
        y:       gfx.y - Phaser.Math.Between(45, 85),
        x:       gfx.x + Phaser.Math.Between(-14, 14),
        scaleX:  2.4, scaleY: 2.4, alpha: 0,
        duration: Phaser.Math.Between(850, 1350),
        delay:    Phaser.Math.Between(80, 380),
        ease:     'Sine.easeOut',
        onComplete: () => { gfx.destroy(); },
      });
    }
  }
}

