      });
    }

    // 외곽 → 중간 → 코어 3겹 (레거시 모드: 황금, 평상시: 붉은 오렌지)
    if (leg) {
      gfx.fillStyle(0xff8800, 0.10); gfx.fillPoints(pts, true);
      const mid  = pts.map(p => ({ x: p.x * 0.70, y: p.y * 0.70 }));
      gfx.fillStyle(0xffcc00, 0.20); gfx.fillPoints(mid, true);
      const core = pts.map(p => ({ x: p.x * 0.42, y: p.y * 0.42 }));
      gfx.fillStyle(0xffee88, 0.28); gfx.fillPoints(core, true);
    } else {
      gfx.fillStyle(0x991100, 0.07); gfx.fillPoints(pts, true);
      const mid  = pts.map(p => ({ x: p.x * 0.70, y: p.y * 0.70 }));
      gfx.fillStyle(0xff4400, 0.13); gfx.fillPoints(mid, true);
      const core = pts.map(p => ({ x: p.x * 0.42, y: p.y * 0.42 }));
      gfx.fillStyle(0xffaa00, 0.18); gfx.fillPoints(core, true);
    }
  }

  // ─────────────────────────────────────────────────────────────────
  // A: 상시 불꽃 오라
  // ─────────────────────────────────────────────────────────────────

  private spawnOraFlame(api: GameSceneAPI): void {
    const scene = api.scene;
    const px    = api.player.x;
    const py    = api.player.y;
    const leg   = this.legacyModeActive;

    const w = leg ? Phaser.Math.Between(5, 9)  : Phaser.Math.Between(3, 6);
    const h = leg ? Phaser.Math.Between(12, 20) : Phaser.Math.Between(8, 14);

    const gfx = scene.add.graphics();

    if (leg) {
      // 레거시 모드: 황금빛 오라
      gfx.fillStyle(0xcc5500, 0.20); gfx.fillPoints(LegacyAbility.flamePts(w,        h       ), true);
      gfx.fillStyle(0xff8800, 0.38); gfx.fillPoints(LegacyAbility.flamePts(w * 0.70, h * 0.76), true);
      gfx.fillStyle(0xffdd00, 0.56); gfx.fillPoints(LegacyAbility.flamePts(w * 0.40, h * 0.50), true);
