import type { CharacterAbility, GameSceneAPI, SpecialPoopType } from './types';

/** 모든 메서드가 no-op인 기본 구현. 각 캐릭터는 이를 상속해 필요한 메서드만 오버라이드. */
export class BaseAbility implements CharacterAbility {
  onCreate(_api: GameSceneAPI): void {}
  getPlayerSpeedBonus(): number { return 0; }
  getTickScore(base: number): number { return base; }
  getSpawnIntervals() { return { gold: 40, diamond: 100, topaz: 180 }; }
  onScoreMilestone(_score: number, _api: GameSceneAPI): void {}
  onCollectSpecial(_type: SpecialPoopType): number { return 0; }
  specialPoopSpeedReduction(_type: 'gold' | 'diamond'): number { return 0; }
  isSpawnBlocked(): boolean { return false; }
  getSpawnCountReduction(): number { return 0; }
  overrideSpawnPoop(_api: GameSceneAPI): boolean { return false; }
  onAfterSpawnPoop(_api: GameSceneAPI): void {}
  onHitPoop(_api: GameSceneAPI): boolean { return false; }
  onUpdate(_api: GameSceneAPI): void {}
}

content.content:
     1→import { BaseAbility } from './BaseAbility';
     2→import type { GameSceneAPI } from './types';
     3→
     4→/**
     5→ * 레거시 (UR)
     6→ * - 기본 효과: 게임 시작 시 6초간 금똥 2개씩 내려오는 피버타임 + 황금 빗줄기(D)
     7→ *             + 똥 스폰마다 20% 확률로 랜덤 2개 화염 추적선(B) + 불태워 소멸 (+10점)
     8→ *             + 캐릭터 주변 상시 불꽃 오라(A)
     9→ * - 특수 능력: 500점마다 레거시 모드 10초 발동
    10→ *             — 점수 1.2배 + 화면 전체 불꽃 폭발 + 황금 빗줄기 강화
    11→ *             — 불태우기 강화: 40% 확률로 4개 소멸 / 오라 황금빛으로 강화
    12→ */
    13→export class LegacyAbility extends BaseAbility {
    14→  private startFeverActive = false;
    15→  private legacyModeActive = false;
    16→  private accum           = 0;
    17→  private lastLegacyScore = 0;
    18→  private legacyTopGlow?:    Phaser.GameObjects.Graphics;
    19→  private legacyPulseTween?: Phaser.Tweens.Tween;
    20→  private legacyRainTimer?:  Phaser.Time.TimerEvent;
    21→
    22→  // A: 상시 불꽃 오라
    23→  private oraTimer = 0;
    24→  private static readonly ORA_INTERVAL_NORMAL = 180; // ms
    25→  private static readonly ORA_INTERVAL_LEGACY =  80; // ms
    26→  private static readonly ORA_COLS_NORMAL = [0xff3300, 0xff6600, 0xffaa00];
    27→  private static readonly ORA_COLS_LEGACY = [0xffaa00, 0xffcc00, 0xffee44, 0xffffff];
    28→
    29→  // D: 빗줄기 색상
    30→  private static readonly RAIN_COLS_FEVER  = [0xff8800, 0xffaa00, 0xffcc00, 0xffee00];
    31→  private static readonly RAIN_COLS_LEGACY = [0xff5500, 0xff8800, 0xffaa00, 0xffcc00];
    32→
    33→  // ── 불꽃 물방울 다각형 좌표 ─────────────────────────────────────────
    34→  private static flamePts(w: number, h: number) {
    35→    return [
    36→      { x:  0,         y: -h        },
    37→      { x:  w * 0.55,  y: -h * 0.1  },
    38→      { x:  w * 0.75,  y:  h * 0.35 },
    39→      { x:  w * 0.3,   y:  h        },
    40→      { x: -w * 0.3,   y:  h        },
    41→      { x: -w * 0.75,  y:  h * 0.35 },
    42→      { x: -w * 0.55,  y: -h * 0.1  },
    43→    ];
    44→  }
    45→
    46→  // ── 8각 별 좌표 (빗줄기 공용) ────────────────────────────────────────
    47→  private static starPts(s: number) {
    48→    return [
    49→      { x:  0,       y: -s       }, { x:  s * 0.4, y: -s * 0.4 },
    50→      { x:  s,       y:  0       }, { x:  s * 0.4, y:  s * 0.4 },
    51→      { x:  0,       y:  s       }, { x: -s * 0.4, y:  s * 0.4 },
    52→      { x: -s,       y:  0       }, { x: -s * 0.4, y: -s * 0.4 },
    53→    ];
    54→  }
    55→
    56→  // ─────────────────────────────────────────────────────────────────
    57→  // 생명주기
    58→  // ─────────────────────────────────────────────────────────────────
    59→
    60→  override onCreate(api: GameSceneAPI): void {
    61→    this.startFeverActive = true;
    62→    this.startFeverRain(api);
    63→    api.scene.time.delayedCall(6000, () => {
    64→      this.startFeverActive = false;
    65→    });
    66→  }
    67→
    68→  override onUpdate(api: GameSceneAPI): void {
    69→    const delta = api.scene.game.loop.delta;
    70→    this.oraTimer += delta;
    71→    const interval = this.legacyModeActive
    72→      ? LegacyAbility.ORA_INTERVAL_LEGACY
    73→      : LegacyAbility.ORA_INTERVAL_NORMAL;
    74→    if (this.oraTimer >= interval) {
    75→      this.oraTimer -= interval;
    76→      this.spawnOraFlame(api);
    77→    }
    78→  }
    79→
    80→  override getTickScore(base: number): number {
    81→    if (!this.legacyModeActive) return base;
    82→    this.accum += base * 0.2;
    83→    const bonus = Math.floor(this.accum);
    84→    this.accum -= bonus;
    85→    return base + bonus;
    86→  }
    87→
    88→  override overrideSpawnPoop(api: GameSceneAPI): boolean {
    89→    if (this.startFeverActive) {
    90→      api.spawnGoldPoop();
    91→      api.spawnGoldPoop();
    92→      return true;
    93→    }
    94→    return false;
    95→  }
    96→
    97→  override onAfterSpawnPoop(api: GameSceneAPI): void {
    98→    const chance = this.legacyModeActive ? 0.6 : 0.3;
    99→    const count  = this.legacyModeActive ? 4   : 2;
   100→    if (Math.random() < chance) {
   101→      this.burnRandomPoops(api, count);
   102→    }
   103→  }
   104→
   105→  override onScoreMilestone(score: number, api: GameSceneAPI): void {
   106→    if (score % 500 === 0 && score > this.lastLegacyScore) {
   107→      this.lastLegacyScore = score;
   108→      this.activateLegacyMode(api);
   109→    }
   110→  }
   111→
   112→  // ─────────────────────────────────────────────────────────────────
   113→  // A: 상시 불꽃 오라
   114→  // ─────────────────────────────────────────────────────────────────
   115→
   116→  private spawnOraFlame(api: GameSceneAPI): void {
   117→    const scene = api.scene;
   118→    const px    = api.player.x;
   119→    const py    = api.player.y;
   120→    const leg   = this.legacyModeActive;
   121→    const cols  = leg ? LegacyAbility.ORA_COLS_LEGACY : LegacyAbility.ORA_COLS_NORMAL;
   122→    const count = leg ? Phaser.Math.Between(5, 7) : Phaser.Math.Between(2, 3);
   123→    const rMax  = leg ? 2.2  : 1.6;
   124→    const aMax  = leg ? 0.90 : 0.70;
   125→    const riseMin = leg ? 20  : 14;
   126→    const riseMax = leg ? 42  : 28;
   127→    const lifeMin = leg ? 280 : 180;
   128→    const lifeMax = leg ? 520 : 380;
   129→
   130→    for (let i = 0; i < count; i++) {
   131→      const gfx = scene.add.graphics();
   132→      const r   = Phaser.Math.FloatBetween(0.8, rMax);
   133→      const col = Phaser.Utils.Array.GetRandom(cols) as number;
   134→      const a   = Phaser.Math.FloatBetween(0.50, aMax);
   135→
   136→      gfx.fillStyle(col, a);
   137→      gfx.fillCircle(0, 0, r);
   138→      gfx.setPosition(
   139→        px + Phaser.Math.Between(-10, 10),
   140→        py + Phaser.Math.Between(10, 24),
   141→      );
   142→      gfx.setDepth(88);
   143→
   144→      scene.tweens.add({
   145→        targets:  gfx,
   146→        y:        gfx.y - Phaser.Math.Between(riseMin, riseMax),
   147→        x:        gfx.x + Phaser.Math.Between(-4, 4),
   148→        alpha:    0,
   149→        scaleX:   0.15,
   150→        scaleY:   0.15,
   151→        duration: Phaser.Math.Between(lifeMin, lifeMax),
   152→        ease:     'Quad.easeOut',
   153→        onComplete: () => { gfx.destroy(); },
   154→      });
   155→    }
   156→  }
   157→
   158→  // ─────────────────────────────────────────────────────────────────
   159→  // B: 화염 추적선
   160→  // ─────────────────────────────────────────────────────────────────
   161→
   162→  private drawFireTrail(
   163→    scene: Phaser.Scene,
   164→    fromX: number, fromY: number,
   165→    toList: { x: number; y: number }[],
   166→  ): void {
   167→    if (toList.length === 0) return;
   168→
   169→    const gfx = scene.add.graphics();
   170→    gfx.setDepth(195);
   171→
   172→    for (const { x, y } of toList) {
   173→      gfx.lineStyle(3.5, 0xff6600, 0.50);
   174→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   175→      gfx.lineStyle(1.5, 0xffee00, 0.75);
   176→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   177→    }
   178→
   179→    scene.tweens.add({
   180→      targets: gfx, alpha: 0, duration: 200, ease: 'Quad.easeOut',
   181→      onComplete: () => { gfx.destroy(); },
   182→    });
   183→  }
   184→
   185→  // ─────────────────────────────────────────────────────────────────
   186→  // C: 레거시 모드 활성화
   187→  // ─────────────────────────────────────────────────────────────────
   188→
   189→  private activateLegacyMode(api: GameSceneAPI): void {
   190→    if (this.legacyModeActive) return;
   191→    this.legacyModeActive = true;
   192→    this.accum = 0;
   193→
   194→    const scene = api.scene;
   195→    const cx    = api.player.x;
   196→    const cy    = api.player.y;
   197→
   198→    // ─ 반투명 플래시 ──────────────────────────────────────────────
   199→    const flashOverlay = scene.add.graphics().setDepth(200);
   200→    flashOverlay.fillStyle(0xffee00, 1);
   201→    flashOverlay.fillRect(0, 0, 400, 600);
   202→    flashOverlay.setAlpha(0.38);
   203→    scene.tweens.add({
   204→      targets: flashOverlay, alpha: 0, duration: 220, ease: 'Quad.easeOut',
   205→      onComplete: () => { flashOverlay.destroy(); },
   206→    });
   207→
   208→    // ─ 팽창 링 2개 ───────────────────────────────────────────────
   209→    [{ delay: 0, maxScale: 4.3 }, { delay: 80, maxScale: 3.4 }].forEach(({ delay, maxScale }) => {
   210→      const ring = scene.add.graphics().setDepth(155);
   211→      ring.lineStyle(2.5, 0xffee00, 0.9);
   212→      ring.strokeEllipse(0, 0, 74, 98);
   213→      ring.setPosition(cx, cy);
   214→      scene.tweens.add({
   215→        targets: ring, scaleX: maxScale, scaleY: maxScale, alpha: 0,
   216→        duration: 500, delay, ease: 'Quad.easeOut',
   217→        onComplete: () => { ring.destroy(); },
   218→      });
   219→    });
   220→
   221→    // ─ 채움 타원 ─────────────────────────────────────────────────
   222→    const fill = scene.add.graphics().setDepth(154);
   223→    fill.fillStyle(0xffaa00, 0.28);
   224→    fill.fillEllipse(0, 0, 74, 98);
   225→    fill.setPosition(cx, cy);
   226→    scene.tweens.add({
   227→      targets: fill, alpha: 0, duration: 180, ease: 'Quad.easeOut',
   228→      onComplete: () => { fill.destroy(); },
   229→    });
   230→
   231→    // ─ 파편 8개 ──────────────────────────────────────────────────
   232→    for (let i = 0; i < 8; i++) {
   233→      const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
   234→      const speed = Phaser.Math.FloatBetween(40, 95);
   235→      const sw    = Phaser.Math.Between(5, 12);
   236→      const sh    = Phaser.Math.Between(2, 5);
   237→      const shard = scene.add.graphics().setDepth(156);
   238→      shard.fillStyle(0xffee00, 1);
   239→      shard.fillRect(-sw / 2, -sh / 2, sw, sh);
   240→      shard.setPosition(cx, cy).setRotation(angle);
   241→      scene.tweens.add({
   242→        targets: shard,
   243→        x: cx + Math.cos(angle) * speed, y: cy + Math.sin(angle) * speed,
   244→        alpha: 0, rotation: angle + Phaser.Math.FloatBetween(-1, 1),
   245→        duration: Phaser.Math.Between(270, 440), ease: 'Quad.easeOut',
   246→        onComplete: () => { shard.destroy(); },
   247→      });
   248→    }
   249→
   250→    // ─ 화면 전체 불꽃 폭발 (20개) ────────────────────────────────
   251→    const BURST_COLS = [0xff2200, 0xff6600, 0xffaa00, 0xffdd00, 0xffff88];
   252→    for (let i = 0; i < 20; i++) {
   253→      const gfx = scene.add.graphics();
   254→      const w   = Phaser.Math.Between(4, 10);
   255→      const h   = Phaser.Math.Between(10, 22);
   256→      const col = Phaser.Utils.Array.GetRandom(BURST_COLS) as number;
   257→
   258→      gfx.fillStyle(col, Phaser.Math.FloatBetween(0.22, 0.50));
   259→      gfx.fillPoints(LegacyAbility.flamePts(w, h), true);
   260→      gfx.fillStyle(0xffee88, Phaser.Math.FloatBetween(0.28, 0.55));
