     2→import { BaseAbility } from './BaseAbility';
     3→import type { GameSceneAPI } from './types';
     4→
     5→/**
     6→ * 매화 (SR)
     7→ * - 기본 효과: 이동 속도 +50px/s
     8→ * - 특수 능력: 100점마다 플레이어 위의 일반 똥 3개를 칼날 슬래시로 삭제
     9→ *   이펙트: 가운데가 넓은 대각선 칼날 + 붉은 매화 잎 낙화
    10→ */
    11→export class MaehwaAbility extends BaseAbility {
    12→  private lastMaehwaScore = 0;
    13→
    14→  override getPlayerSpeedBonus(): number {
    15→    return 50;
    16→  }
    17→
    18→  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    19→    if (!api.isClassicMode) return;
    20→    if (score % 100 === 0 && score > this.lastMaehwaScore) {
    21→      this.lastMaehwaScore = score;
    22→      this.slashClosestPoops(3, api);
    23→    }
    24→  }
    25→
    26→  private slashClosestPoops(count: number, api: GameSceneAPI): void {
    27→    const active = api.poops
    28→      .getChildren()
    29→      .filter(p => {
    30→        const sp = p as Phaser.Physics.Arcade.Sprite;
    31→        return sp.active && sp.y < api.player.y;
    32→      }) as Phaser.Physics.Arcade.Sprite[];
    33→
    34→    active.sort((a, b) => {
    35→      const da = Phaser.Math.Distance.Between(api.player.x, api.player.y, a.x, a.y);
    36→      const db = Phaser.Math.Distance.Between(api.player.x, api.player.y, b.x, b.y);
    37→      return da - db;
    38→    });
    39→
    40→    active.slice(0, count).forEach(poop => {
    41→      this.drawSlashEffect(poop.x, poop.y, api);
    42→      this.spawnPetals(poop.x, poop.y, api);
    43→      poop.destroy();
    44→    });
    45→  }
    46→
    47→  /** 가운데가 넓은 대각선(↗) 칼날 이펙트 */
    48→  private drawSlashEffect(cx: number, cy: number, api: GameSceneAPI): void {
    49→    const gfx = api.scene.add.graphics().setDepth(120);
    50→
    51→    // 칼날: fillPoints로 ↗ 방향 마름모꼴 (끝은 뾰족, 중앙은 넓음)
    52→    const len = 26; // 반길이
    53→    const wid = 7;  // 중앙 최대 반폭
    54→    // ↗ 방향 slash: (cx-len, cy+len) → (cx+len, cy-len) 축
    55→    gfx.fillStyle(0xff3366, 0.9);
    56→    gfx.fillPoints([
    57→      new Phaser.Geom.Point(cx - len, cy + len),          // 좌하 끝
    58→      new Phaser.Geom.Point(cx - wid * 0.4, cy + wid),    // 좌상 측면
    59→      new Phaser.Geom.Point(cx + len, cy - len),          // 우상 끝
    60→      new Phaser.Geom.Point(cx + wid * 0.4, cy - wid),    // 우하 측면
    61→    ], true);
    62→
    63→    // 외곽 흰색 글로우
    64→    gfx.lineStyle(3, 0xffffff, 0.5);
    65→    gfx.lineBetween(cx - len, cy + len, cx + len, cy - len);
    66→
    67→    api.scene.tweens.add({
    68→      targets: gfx,
    69→      alpha: 0,
    70→      duration: 300,
    71→      onComplete: () => gfx.destroy(),
    72→    });
    73→  }
    74→
    75→  /** 붉은 매화 잎 여러 개 낙화 */
    76→  private spawnPetals(cx: number, cy: number, api: GameSceneAPI): void {
    77→    const PETAL_COUNT = 7;
    78→    for (let i = 0; i < PETAL_COUNT; i++) {
