/**
 * 매화 (SR) — 이동속도 + 칼 베기
 * ★0: +50px/s / 100점마다 3개  / ★1: +65px/s / 90점마다 3개
 * ★2: +80px/s / 80점마다 4개   / ★3: +100px/s / 70점마다 5개 + 금·다이아도 베어 수집 (+5점 추가)
 */
export class MaehwaAbility extends BaseAbility {
  private lastMaehwaScore = 0;

  private static readonly SPEED    = [50, 65, 80, 100] as const;
  private static readonly INTERVAL = [100, 90, 80, 70] as const;
  private static readonly COUNT    = [3, 3, 4, 5] as const;

  override getPlayerSpeedBonus(): number {
    return MaehwaAbility.SPEED[this.awakeningLevel] ?? 100;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (!api.isClassicMode) return;
    const interval = MaehwaAbility.INTERVAL[this.awakeningLevel] ?? 70;
    if (score % interval === 0 && score > this.lastMaehwaScore) {
      this.lastMaehwaScore = score;
      const count = MaehwaAbility.COUNT[this.awakeningLevel] ?? 5;
      this.slashClosestPoops(count, api);
    }
  }

  private slashClosestPoops(count: number, api: GameSceneAPI): void {
    const active = api.poops
      .getChildren()
      .filter(p => {
        const sp = p as Phaser.Physics.Arcade.Sprite;
        return sp.active && sp.y < api.player.y;
      }) as Phaser.Physics.Arcade.Sprite[];

    active.sort((a, b) => {
      const da = Phaser.Math.Distance.Between(api.player.x, api.player.y, a.x, a.y);
      const db = Phaser.Math.Distance.Between(api.player.x, api.player.y, b.x, b.y);
      return da - db;
    });

    active.slice(0, count).forEach(poop => {
      this.drawSlashEffect(poop.x, poop.y, api);
      this.spawnPetals(poop.x, poop.y, api);
      poop.destroy();
    });

    // ★3: 금·다이아똥도 베어 수집 (+5점 추가)
    if (this.awakeningLevel >= 3) {
      this.slashSpecialPoops(api);
    }
  }

  private slashSpecialPoops(api: GameSceneAPI): void {
    const specials = [
      ...api.goldPoops.getChildren(),
      ...api.diamondPoops.getChildren(),
    ].filter(p => {
      const sp = p as Phaser.Physics.Arcade.Sprite;
      return sp.active && sp.y < api.player.y;
    }) as Phaser.Physics.Arcade.Sprite[];

    specials.slice(0, 2).forEach(poop => {
      this.drawSlashEffect(poop.x, poop.y, api);
      this.spawnPetals(poop.x, poop.y, api);
      if (api.goldPoops.contains(poop))    api.collectGoldPoop(poop);
      else                                  api.collectDiamondPoop(poop);
      api.updateScore(5); // 추가 보너스
    });
  }

