  private accum = 0;

  private static readonly MULTIPLIER = [0.10, 0.13, 0.16, 0.20] as const;
  private static readonly INTERVAL   = [200, 180, 160, 140] as const;
  private static readonly BONUS      = [20, 25, 30, 40] as const;

  override getTickScore(base: number): number {
    const extra = ArchieveAbility.MULTIPLIER[this.awakeningLevel] ?? 0.20;
    this.accum += base * extra;
    const bonus = Math.floor(this.accum);
    this.accum -= bonus;
    return base + bonus;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (this.isProcessingBonus) return;
    const interval = ArchieveAbility.INTERVAL[this.awakeningLevel] ?? 140;
    if (score % interval === 0 && score > this.lastArchieveScore) {
      this.lastArchieveScore = score;
      this.isProcessingBonus = true;
      const pts = ArchieveAbility.BONUS[this.awakeningLevel] ?? 40;
      api.updateScore(pts);
      // ★3: 일반 똥 3개 아카이빙(파괴) + 각 +3점
      if (this.awakeningLevel >= 3) {
        this.archivePoops(3, api);
      }
      this.isProcessingBonus = false;
    }
  }

  private archivePoops(count: number, api: GameSceneAPI): void {
    const active = (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active);
    active.sort(() => Math.random() - 0.5);
    active.slice(0, count).forEach(p => {
      p.destroy();
      api.updateScore(3);
    });
  }
}

