import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 루트 (SR) — 터미널 삭제
 * ★0: 100점마다 7개  / ★1: 90점마다 7개
 * ★2: 80점마다 8개   / ★3: 70점마다 9개
 */
export class HackerAbility extends BaseAbility {
  private lastHackerScore = 0;
  private static readonly INTERVAL = [100, 90, 80, 70] as const;
  private static readonly DELETE_COUNT = [7, 7, 8, 9] as const;

  override specialPoopSpeedReduction(_type: 'gold' | 'diamond'): number {
    return 40;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (!api.isClassicMode) return;
    const interval = HackerAbility.INTERVAL[this.awakeningLevel] ?? 70;
    if (score % interval === 0 && score > this.lastHackerScore) {
      this.lastHackerScore = score;
      const count = HackerAbility.DELETE_COUNT[this.awakeningLevel] ?? 9;
      this.removeRandomPoops(count, api);
    }
  }

  private removeRandomPoops(count: number, api: GameSceneAPI): void {
    const active = api.poops
      .getChildren()
      .filter(p => (p as Phaser.GameObjects.GameObject).active) as Phaser.Physics.Arcade.Sprite[];

    active.sort(() => Math.random() - 0.5);
    active.slice(0, count).forEach(p => {
      (p.body as Phaser.Physics.Arcade.Body).setVelocity(0, 0);
      this.playTerminalEffect(p.x, p.y, api);
      p.destroy();
    });
  }

  /** 초록 테두리 검정 박스 flash → 픽셀 비산 */
  private playTerminalEffect(cx: number, cy: number, api: GameSceneAPI): void {
    const scene = api.scene;
    const BOX_W = 36, BOX_H = 36;

    // ── 1. 검정 박스 + 초록 테두리 ──────────────────────────────────
    const box = scene.add.graphics().setDepth(110);
    box.fillStyle(0x000000, 1);
    box.fillRect(-BOX_W / 2, -BOX_H / 2, BOX_W, BOX_H);
    box.lineStyle(2, 0x00ff41, 1);
    box.strokeRect(-BOX_W / 2, -BOX_H / 2, BOX_W, BOX_H);
    box.setPosition(cx, cy);

    // 짧게 flash 후 사라짐
    scene.tweens.add({
      targets: box,
      alpha: 0,
      duration: 180,
      delay: 60,
      onComplete: () => box.destroy(),
    });

    // ── 2. 초록 픽셀 파편 비산 ───────────────────────────────────────
    const PIXEL_COUNT = 10;
    const GREEN = 0x00ff41;

    for (let i = 0; i < PIXEL_COUNT; i++) {
      const size   = Phaser.Math.Between(4, 9);
      const angle  = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const speed  = Phaser.Math.FloatBetween(40, 110);
      const tx     = cx + Math.cos(angle) * speed;
      const ty     = cy + Math.sin(angle) * speed;

      const px = scene.add.graphics().setDepth(111);
      px.fillStyle(GREEN, 1);
      px.fillRect(0, 0, size, size);
      px.setPosition(cx, cy);

      scene.tweens.add({
        targets: px,
        x: tx,
        y: ty + Phaser.Math.Between(10, 30), // 중력감
        alpha: 0,
        duration: Phaser.Math.Between(250, 420),
        ease: 'Quad.easeOut',
        onComplete: () => px.destroy(),
      });
    }
  }
}

import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI, SpecialPoopType } from './types';

/**
 * 광부 (SR) — 무지개똥 + 수집 보너스
 * ★0: +10점 / 200점마다  / ★1: +12점 / 180점마다
 * ★2: +15점 / 160점마다  / ★3: +20점 / 140점마다 + 무지개 수집 시 3초 자석
 */
export class MinerAbility extends BaseAbility {
  private lastRainbowScore = 0;
  private magnetActive = false;
  private magnetEndTime = 0;

  private static readonly BONUS    = [10, 12, 15, 20] as const;
  private static readonly INTERVAL = [200, 180, 160, 140] as const;
  private static readonly MAGNET_SPEED = 180;

  override onCollectSpecial(type: SpecialPoopType): number {
    const bonus = MinerAbility.BONUS[this.awakeningLevel] ?? 20;
    if (this.awakeningLevel >= 3 && type === 'rainbow') {
      this.magnetActive  = true;
      this.magnetEndTime = Date.now() + 3000;
    }
    return bonus;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    const interval = MinerAbility.INTERVAL[this.awakeningLevel] ?? 140;
    if (score % interval === 0 && score > this.lastRainbowScore) {
      this.lastRainbowScore = score;
      api.spawnRainbowPoop();
    }
  }

  /** 자석 효과: 특수 똥을 플레이어 쪽으로 끌어당김 */
  override onUpdate(api: GameSceneAPI): void {
    if (!this.magnetActive) return;
    if (Date.now() >= this.magnetEndTime) {
      this.magnetActive = false;
      return;
    }
    const px  = api.player.x;
    const py  = api.player.y;
    const spd = MinerAbility.MAGNET_SPEED;

    const allSpecial = [
      ...api.goldPoops.getChildren(),
      ...api.diamondPoops.getChildren(),
      ...api.topazPoops.getChildren(),
      ...api.rainbowPoops.getChildren(),
    ] as Phaser.Physics.Arcade.Sprite[];

    for (const poop of allSpecial) {
      if (!poop.active) continue;
      const dx   = px - poop.x;
      const dy   = py - poop.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < 5) continue;
      (poop.body as Phaser.Physics.Arcade.Body).setVelocity(
        (dx / dist) * spd,
        (dy / dist) * spd,
      );
    }
  }
}

