import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 노이즈 (SR) — 특수 똥 생성 단축 + 소환 감소
 * ★0: 25%단축 / 200점마다 -2개  / ★1: 30%단축 / 180점마다 -2개
 * ★2: 35%단축 / 160점마다 -3개  / ★3: 40%단축 / 140점마다 -4개 + 금똥 1개 강제 소환
 */
export class NoiseAbility extends BaseAbility {
  private pendingReduction = 0;

  // 기준: gold 40, diamond 100, topaz 180
  private static readonly INTERVALS = [
    { gold: 30, diamond: 75,  topaz: 135 }, // 25% 단축
    { gold: 28, diamond: 70,  topaz: 126 }, // 30% 단축
    { gold: 26, diamond: 65,  topaz: 117 }, // 35% 단축
    { gold: 24, diamond: 60,  topaz: 108 }, // 40% 단축
  ] as const;

  private static readonly TRIGGER_INTERVAL = [200, 180, 160, 140] as const;
  private static readonly REDUCTION        = [2, 2, 3, 4] as const;

  override getSpawnIntervals() {
    return { ...NoiseAbility.INTERVALS[this.awakeningLevel] ?? NoiseAbility.INTERVALS[3] };
  }

  override getSpawnCountReduction(): number {
    const r = this.pendingReduction;
    this.pendingReduction = 0;
    return r;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    const interval = NoiseAbility.TRIGGER_INTERVAL[this.awakeningLevel] ?? 140;
    if (score % interval === 0) {
      this.pendingReduction = NoiseAbility.REDUCTION[this.awakeningLevel] ?? 4;
      // ★3: 소환 감소 발동 시 금똥 1개 강제 소환
      if (this.awakeningLevel >= 3) {
        api.spawnGoldPoop();
      }
    }
  }
}

