     5→/**
     6→ * 센티넬 (UR) — 보호막
     7→ * ★0: 2개 시작 / 300점마다 충전 / 최대 3  / ★1: 2개 / 250점마다 / 최대 4
     8→ * ★2: 3개 시작 / 200점마다 충전 / 최대 4  / ★3: 3개 / 150점마다 / 최대 5 + 흡수 시 연쇄 전기 3개 추가 제거
     9→ * - UI: 붉은 공이 허리 주변 수평 궤도 공전 + 전기 파지직 (재사용 Graphics)
    10→ */
    11→export class SentinelAbility extends BaseAbility {
    12→  private shieldCount = 0;
    13→
    14→  private static readonly START_SHIELDS   = [2, 2, 3, 3, 4, 4] as const;
    15→  private static readonly CHARGE_INTERVAL = [300, 250, 200, 150, 120, 100] as const;
    16→  private static readonly MAX_SHIELDS     = [3, 4, 4, 5, 5, 6] as const;
    17→  private orbitDroplets: Phaser.GameObjects.Graphics[] = [];
    18→  private orbitAngle = 0;
    19→
    20→  // ── 전기 스파크: persistent Graphics 재사용 (동적 생성 없음) ──
    21→  private sparkGfx: Phaser.GameObjects.Graphics | null = null;
    22→  private sparkTween: Phaser.Tweens.Tween | null = null;
    23→  private sparkTimer = 0;
    24→
    25→  private static readonly ORBIT_SPEED   = 3.0;
    26→  private static readonly ORBIT_RX      = 26;
    27→  private static readonly ORBIT_RY      = 7;
    28→  private static readonly ORBIT_WAIST_Y = 8;
    29→  private static readonly RED           = 0xff2222;
    30→  private static readonly RED_LIGHT     = 0xff6666;
    31→
    32→  override onCreate(api: GameSceneAPI): void {
    33→    const start = SentinelAbility.START_SHIELDS[this.awakeningLevel] ?? 3;
    34→    this.shieldCount = start;
    35→    this.spawnDroplets(api, start);
    36→    this.sparkGfx = api.scene.add.graphics().setDepth(96).setAlpha(0);
    37→  }
    38→
    39→  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    40→    const interval = SentinelAbility.CHARGE_INTERVAL[this.awakeningLevel] ?? 150;
    41→    const maxShields = SentinelAbility.MAX_SHIELDS[this.awakeningLevel] ?? 5;
    42→    if (score % interval === 0 && this.shieldCount < maxShields) {
    43→      this.shieldCount++;
    44→      this.playShieldChargeEffect(api);
    45→      this.spawnDroplets(api, 1);
    46→    }
    47→  }
    48→
    49→  override onHitPoop(api: GameSceneAPI): boolean {
    50→    if (this.shieldCount > 0) {
    51→      this.shieldCount--;
    52→      this.scatterDroplets(api, 1);
    53→      this.playShieldBreakEffect(api);
    54→      this.zapNearbyPoops(api, 320);
    55→      // ★3: 연쇄 전기 3개 / ★5: 5개
    56→      if (this.awakeningLevel >= 3) {
    57→        this.chainZapPoops(api, this.awakeningLevel >= 5 ? 5 : 3, 320);
    58→      }
    59→      return true;
    60→    }
    61→    return false;
    62→  }
    63→
    64→  override onUpdate(api: GameSceneAPI): void {
    65→    if (this.orbitDroplets.length === 0) return;
    66→
    67→    const delta  = api.scene.game.loop.delta / 1000;
    68→    const deltMs = api.scene.game.loop.delta;
    69→    this.orbitAngle += SentinelAbility.ORBIT_SPEED * delta;
    70→
    71→    const cx    = api.player.x;
    72→    const cy    = api.player.y + SentinelAbility.ORBIT_WAIST_Y;
    73→    const total = this.orbitDroplets.length;
    74→    const RX    = SentinelAbility.ORBIT_RX;
    75→    const RY    = SentinelAbility.ORBIT_RY;
    76→
    77→    this.orbitDroplets.forEach((drop, i) => {
    78→      if (!drop.active) return;
    79→      const angle = this.orbitAngle + (i / total) * Math.PI * 2;
    80→      const sinA  = Math.sin(angle);
    81→
    82→      drop.setPosition(cx + Math.cos(angle) * RX, cy + sinA * RY);
    83→
    84→      const t = (sinA + 1) / 2;
    85→      drop.setScale(0.55 + 0.55 * t);
    86→      drop.setAlpha(0.35 + 0.65 * t);
    87→      drop.setDepth(sinA > 0 ? 101 : 89);
    88→    });
    89→
    90→    // 전기 파지직: 250ms마다 persistent sparkGfx를 clear+redraw
    91→    this.sparkTimer += deltMs;
    92→    if (this.sparkTimer >= 250) {
    93→      this.sparkTimer = 0;
    94→      this.redrawSparks(api);
    95→    }
    96→  }
    97→
    98→  // ─────────────────────────────────────────────────────────────
    99→  // 전기 스파크 (재사용 Graphics)
   100→  // ─────────────────────────────────────────────────────────────
   101→
   102→  /** persistent sparkGfx를 clear 후 몸+공 스파크를 새로 그리고 alpha tween */
   103→  private redrawSparks(api: GameSceneAPI): void {
   104→    const g = this.sparkGfx;
   105→    if (!g?.active) return;
   106→
   107→    g.clear();
   108→    g.setAlpha(1);
   109→    this.sparkTween?.stop();
   110→
   111→    // 몸 주변 스파크 (굵게)
   112→    const ba    = Phaser.Math.FloatBetween(0, Math.PI * 2);
   113→    const br    = Phaser.Math.FloatBetween(18, 34);
   114→    this.drawSparkLine(g, api.player.x + Math.cos(ba) * br, api.player.y + Math.sin(ba) * br * 0.6, 2.5, 10);
   115→
   116→    // 공 주변 스파크 (가늘게, 40% 확률 per droplet)
   117→    this.orbitDroplets.forEach(drop => {
   118→      if (drop.active && drop.alpha > 0.5 && Math.random() < 0.4) {
   119→        this.drawSparkLine(g, drop.x, drop.y, 1, 7);
   120→      }
   121→    });
   122→
   123→    this.sparkTween = api.scene.tweens.add({
   124→      targets: g,
   125→      alpha: 0,
   126→      duration: 200,
   127→      ease: 'Quad.easeOut',
   128→    });
   129→  }
   130→
   131→  /** 전달받은 Graphics에 지그재그 라인을 직접 그림 (새 객체 생성 없음) */
   132→  private drawSparkLine(g: Phaser.GameObjects.Graphics, ox: number, oy: number, thickness: number, segLen: number): void {
   133→    const color = Math.random() < 0.6 ? 0xff3333 : 0xff7744;
   134→    g.lineStyle(thickness, color, 1);
   135→    g.beginPath();
   136→    let px = ox + Phaser.Math.Between(-5, 5);
   137→    let py = oy + Phaser.Math.Between(-5, 5);
   138→    g.moveTo(px, py);
   139→    const segs = Phaser.Math.Between(2, 4);
   140→    for (let j = 0; j < segs; j++) {
   141→      px += Phaser.Math.Between(-segLen, segLen);
   142→      py += Phaser.Math.Between(-segLen, segLen);
   143→      g.lineTo(px, py);
   144→    }
   145→    g.strokePath();
   146→  }
   147→
   148→  // ─────────────────────────────────────────────────────────────
   149→  // 방울 관리
   150→  // ─────────────────────────────────────────────────────────────
   151→
   152→  private spawnDroplets(api: GameSceneAPI, count: number): void {
   153→    const scene = api.scene;
   154→    for (let i = 0; i < count; i++) {
   155→      const g = scene.add.graphics().setDepth(95);
   156→      this.drawDroplet(g);
   157→      g.setPosition(api.player.x, api.player.y + SentinelAbility.ORBIT_WAIST_Y);
   158→      g.setAlpha(0);
   159→      this.orbitDroplets.push(g);
   160→      scene.tweens.add({ targets: g, alpha: 1, scaleX: 1, scaleY: 1, duration: 350, delay: i * 50, ease: 'Back.easeOut' });
   161→    }
   162→  }
   163→
   164→  private scatterDroplets(api: GameSceneAPI, count: number): void {
   165→    const scene   = api.scene;
   166→    const removed = this.orbitDroplets.splice(0, count);
   167→    removed.forEach(drop => {
   168→      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
   169→      const dist  = Phaser.Math.FloatBetween(30, 55);
   170→      scene.tweens.add({
   171→        targets: drop,
   172→        x: drop.x + Math.cos(angle) * dist,
   173→        y: drop.y + Math.sin(angle) * dist,
   174→        alpha: 0, scaleX: 0.1, scaleY: 0.1,
   175→        duration: 120, ease: 'Quad.easeIn',
   176→        onComplete: () => drop.destroy(),
   177→      });
   178→    });
   179→  }
   180→
   181→  private drawDroplet(g: Phaser.GameObjects.Graphics): void {
   182→    g.clear();
   183→    g.fillStyle(SentinelAbility.RED, 0.22);
   184→    g.fillCircle(0, 0, 15);
   185→    g.fillStyle(SentinelAbility.RED, 0.4);
   186→    g.fillCircle(0, 0, 10);
   187→    g.fillStyle(SentinelAbility.RED, 0.95);
   188→    g.fillCircle(0, 0, 7);
   189→    g.fillStyle(0xffffff, 0.5);
   190→    g.fillCircle(-2, -2.5, 2.5);
   191→  }
   192→
   193→  // ─────────────────────────────────────────────────────────────
   194→  // 파장 범위 내 똥 제거
