     1→import { BaseAbility } from './BaseAbility';
     2→import type { GameSceneAPI } from './types';
     3→
     4→/**
     5→ * 레거시 (UR) — 피버 + 레거시 모드
     6→ * ★0: 6초 피버 / 불태우기 30%/2개(일반) 60%/4개(레거시) / 500점마다 / 10초 / 1.2배
     7→ * ★1: 8초 / 35%/2개 65%/4개 / 450점마다 / 10초 / 1.25배
     8→ * ★2: 10초 / 40%/3개 70%/4개 / 400점마다 / 12초 / 1.30배
     9→ * ★3: 12초 / 45%/3개 75%/4개 / 350점마다 / 15초 / 1.35배 + 모드 종료 직후 3초 미니 피버
    10→ */
    11→export class LegacyAbility extends BaseAbility {
    12→  private startFeverActive = false;
    13→  private legacyModeActive = false;
    14→  private accum           = 0;
    15→  private lastLegacyScore = 0;
    16→
    17→  private static readonly FEVER_DURATION   = [6000, 8000, 10000, 12000, 14000, 16000] as const;
    18→  private static readonly LEGACY_INTERVAL  = [500, 450, 400, 350, 300, 250] as const;
    19→  private static readonly LEGACY_DURATION  = [10000, 10000, 12000, 15000, 18000, 20000] as const;
    20→  private static readonly SCORE_EXTRA      = [0.20, 0.25, 0.30, 0.35, 0.42, 0.50] as const;
    21→  private static readonly BURN_CHANCE_N    = [0.30, 0.35, 0.40, 0.45, 0.50, 0.55] as const;
    22→  private static readonly BURN_CHANCE_L    = [0.60, 0.65, 0.70, 0.75, 0.80, 0.85] as const;
    23→  private static readonly BURN_COUNT_N     = [2, 2, 3, 3, 4, 4] as const;
    24→  private static readonly BURN_COUNT_L     = [4, 4, 4, 4, 5, 5] as const;
    25→  private legacyTopGlow?:    Phaser.GameObjects.Graphics;
    26→  private legacyPulseTween?: Phaser.Tweens.Tween;
    27→  private legacyRainTimer?:  Phaser.Time.TimerEvent;
    28→
    29→  // A: 상시 불꽃 오라
    30→  private oraTimer = 0;
    31→  private static readonly ORA_INTERVAL_NORMAL = 180; // ms
    32→  private static readonly ORA_INTERVAL_LEGACY =  80; // ms
    33→  private static readonly ORA_COLS_NORMAL = [0xff3300, 0xff6600, 0xffaa00];
    34→  private static readonly ORA_COLS_LEGACY = [0xffaa00, 0xffcc00, 0xffee44, 0xffffff];
    35→
    36→  // D: 빗줄기 색상
    37→  private static readonly RAIN_COLS_FEVER  = [0xff8800, 0xffaa00, 0xffcc00, 0xffee00];
    38→  private static readonly RAIN_COLS_LEGACY = [0xff5500, 0xff8800, 0xffaa00, 0xffcc00];
    39→
    40→  // ── 불꽃 물방울 다각형 좌표 ─────────────────────────────────────────
    41→  private static flamePts(w: number, h: number) {
    42→    return [
    43→      { x:  0,         y: -h        },
    44→      { x:  w * 0.55,  y: -h * 0.1  },
    45→      { x:  w * 0.75,  y:  h * 0.35 },
    46→      { x:  w * 0.3,   y:  h        },
    47→      { x: -w * 0.3,   y:  h        },
    48→      { x: -w * 0.75,  y:  h * 0.35 },
    49→      { x: -w * 0.55,  y: -h * 0.1  },
    50→    ];
    51→  }
    52→
    53→  // ── 8각 별 좌표 (빗줄기 공용) ────────────────────────────────────────
    54→  private static starPts(s: number) {
    55→    return [
    56→      { x:  0,       y: -s       }, { x:  s * 0.4, y: -s * 0.4 },
    57→      { x:  s,       y:  0       }, { x:  s * 0.4, y:  s * 0.4 },
    58→      { x:  0,       y:  s       }, { x: -s * 0.4, y:  s * 0.4 },
    59→      { x: -s,       y:  0       }, { x: -s * 0.4, y: -s * 0.4 },
    60→    ];
    61→  }
    62→
    63→  // ─────────────────────────────────────────────────────────────────
    64→  // 생명주기
    65→  // ─────────────────────────────────────────────────────────────────
    66→
    67→  override onCreate(api: GameSceneAPI): void {
    68→    this.startFeverActive = true;
    69→    this.startFeverRain(api);
    70→    const feverDur = LegacyAbility.FEVER_DURATION[this.awakeningLevel] ?? 12000;
    71→    api.scene.time.delayedCall(feverDur, () => {
    72→      this.startFeverActive = false;
    73→    });
    74→  }
    75→
    76→  override onUpdate(api: GameSceneAPI): void {
    77→    const delta = api.scene.game.loop.delta;
    78→    this.oraTimer += delta;
    79→    const interval = this.legacyModeActive
    80→      ? LegacyAbility.ORA_INTERVAL_LEGACY
    81→      : LegacyAbility.ORA_INTERVAL_NORMAL;
    82→    if (this.oraTimer >= interval) {
    83→      this.oraTimer -= interval;
    84→      this.spawnOraFlame(api);
    85→    }
    86→  }
    87→
    88→  override getTickScore(base: number): number {
    89→    if (!this.legacyModeActive) return base;
    90→    const extra = LegacyAbility.SCORE_EXTRA[this.awakeningLevel] ?? 0.35;
    91→    this.accum += base * extra;
    92→    const bonus = Math.floor(this.accum);
    93→    this.accum -= bonus;
    94→    return base + bonus;
    95→  }
    96→
    97→  override overrideSpawnPoop(api: GameSceneAPI): boolean {
    98→    if (this.startFeverActive) {
    99→      api.spawnGoldPoop();
   100→      api.spawnGoldPoop();
   101→      return true;
   102→    }
   103→    return false;
   104→  }
   105→
   106→  override onAfterSpawnPoop(api: GameSceneAPI): void {
   107→    const chance = this.legacyModeActive
   108→      ? (LegacyAbility.BURN_CHANCE_L[this.awakeningLevel] ?? 0.75)
   109→      : (LegacyAbility.BURN_CHANCE_N[this.awakeningLevel] ?? 0.45);
   110→    const count = this.legacyModeActive
   111→      ? (LegacyAbility.BURN_COUNT_L[this.awakeningLevel] ?? 4)
   112→      : (LegacyAbility.BURN_COUNT_N[this.awakeningLevel] ?? 3);
   113→    if (Math.random() < chance) {
   114→      this.burnRandomPoops(api, count);
   115→    }
   116→  }
   117→
   118→  override onScoreMilestone(score: number, api: GameSceneAPI): void {
   119→    const interval = LegacyAbility.LEGACY_INTERVAL[this.awakeningLevel] ?? 350;
   120→    if (score % interval === 0 && score > this.lastLegacyScore) {
   121→      this.lastLegacyScore = score;
   122→      this.activateLegacyMode(api);
   123→    }
   124→  }
   125→
   126→  // ─────────────────────────────────────────────────────────────────
   127→  // A: 상시 불꽃 오라
   128→  // ─────────────────────────────────────────────────────────────────
   129→
   130→  private spawnOraFlame(api: GameSceneAPI): void {
   131→    const scene = api.scene;
   132→    const px    = api.player.x;
   133→    const py    = api.player.y;
   134→    const leg   = this.legacyModeActive;
   135→    const cols  = leg ? LegacyAbility.ORA_COLS_LEGACY : LegacyAbility.ORA_COLS_NORMAL;
   136→    const count = leg ? Phaser.Math.Between(5, 7) : Phaser.Math.Between(2, 3);
   137→    const rMax  = leg ? 2.2  : 1.6;
   138→    const aMax  = leg ? 0.90 : 0.70;
   139→    const riseMin = leg ? 20  : 14;
   140→    const riseMax = leg ? 42  : 28;
   141→    const lifeMin = leg ? 280 : 180;
   142→    const lifeMax = leg ? 520 : 380;
   143→
   144→    for (let i = 0; i < count; i++) {
   145→      const gfx = scene.add.graphics();
   146→      const r   = Phaser.Math.FloatBetween(0.8, rMax);
   147→      const col = Phaser.Utils.Array.GetRandom(cols) as number;
   148→      const a   = Phaser.Math.FloatBetween(0.50, aMax);
   149→
   150→      gfx.fillStyle(col, a);
   151→      gfx.fillCircle(0, 0, r);
   152→      gfx.setPosition(
   153→        px + Phaser.Math.Between(-10, 10),
   154→        py + Phaser.Math.Between(10, 24),
   155→      );
   156→      gfx.setDepth(88);
   157→
   158→      scene.tweens.add({
   159→        targets:  gfx,
   160→        y:        gfx.y - Phaser.Math.Between(riseMin, riseMax),
   161→        x:        gfx.x + Phaser.Math.Between(-4, 4),
   162→        alpha:    0,
   163→        scaleX:   0.15,
   164→        scaleY:   0.15,
   165→        duration: Phaser.Math.Between(lifeMin, lifeMax),
   166→        ease:     'Quad.easeOut',
   167→        onComplete: () => { gfx.destroy(); },
   168→      });
   169→    }
   170→  }
   171→
   172→  // ─────────────────────────────────────────────────────────────────
   173→  // B: 화염 추적선
   174→  // ─────────────────────────────────────────────────────────────────
   175→
   176→  private drawFireTrail(
   177→    scene: Phaser.Scene,
   178→    fromX: number, fromY: number,
   179→    toList: { x: number; y: number }[],
   180→  ): void {
   181→    if (toList.length === 0) return;
   182→
   183→    const gfx = scene.add.graphics();
   184→    gfx.setDepth(195);
   185→
   186→    for (const { x, y } of toList) {
   187→      gfx.lineStyle(3.5, 0xff6600, 0.50);
   188→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   189→      gfx.lineStyle(1.5, 0xffee00, 0.75);
   190→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   191→    }
   192→
   193→    scene.tweens.add({
   194→      targets: gfx, alpha: 0, duration: 200, ease: 'Quad.easeOut',
   195→      onComplete: () => { gfx.destroy(); },
   196→    });
   197→  }
   198→
   199→  // ─────────────────────────────────────────────────────────────────
   200→  // C: 레거시 모드 활성화
   201→  // ─────────────────────────────────────────────────────────────────
   202→
   203→  private activateLegacyMode(api: GameSceneAPI): void {
   204→    if (this.legacyModeActive) return;
   205→    this.legacyModeActive = true;
   206→    this.accum = 0;
   207→
   208→    const scene = api.scene;
   209→    const cx    = api.player.x;
   210→    const cy    = api.player.y;
   211→
   212→    // ─ 반투명 플래시 ──────────────────────────────────────────────
   213→    const flashOverlay = scene.add.graphics().setDepth(200);
   214→    flashOverlay.fillStyle(0xffee00, 1);
   215→    flashOverlay.fillRect(0, 0, 400, 600);
   216→    flashOverlay.setAlpha(0.38);
   217→    scene.tweens.add({
   218→      targets: flashOverlay, alpha: 0, duration: 220, ease: 'Quad.easeOut',
   219→      onComplete: () => { flashOverlay.destroy(); },
   220→    });
   221→
   222→    // ─ 팽창 링 2개 ───────────────────────────────────────────────
   223→    [{ delay: 0, maxScale: 4.3 }, { delay: 80, maxScale: 3.4 }].forEach(({ delay, maxScale }) => {
   224→      const ring = scene.add.graphics().setDepth(155);
   225→      ring.lineStyle(2.5, 0xffee00, 0.9);
   226→      ring.strokeEllipse(0, 0, 74, 98);
   227→      ring.setPosition(cx, cy);
   228→      scene.tweens.add({
   229→        targets: ring, scaleX: maxScale, scaleY: maxScale, alpha: 0,
   230→        duration: 500, delay, ease: 'Quad.easeOut',
   231→        onComplete: () => { ring.destroy(); },
   232→      });
   233→    });
   234→
   235→    // ─ 채움 타원 ─────────────────────────────────────────────────
   236→    const fill = scene.add.graphics().setDepth(154);
   237→    fill.fillStyle(0xffaa00, 0.28);
   238→    fill.fillEllipse(0, 0, 74, 98);
   239→    fill.setPosition(cx, cy);
   240→    scene.tweens.add({
   241→      targets: fill, alpha: 0, duration: 180, ease: 'Quad.easeOut',
   242→      onComplete: () => { fill.destroy(); },
   243→    });
   244→
   245→    // ─ 파편 8개 ──────────────────────────────────────────────────
   246→    for (let i = 0; i < 8; i++) {
   247→      const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
   248→      const speed = Phaser.Math.FloatBetween(40, 95);
   249→      const sw    = Phaser.Math.Between(5, 12);
   250→      const sh    = Phaser.Math.Between(2, 5);
   251→      const shard = scene.add.graphics().setDepth(156);
   252→      shard.fillStyle(0xffee00, 1);
   253→      shard.fillRect(-sw / 2, -sh / 2, sw, sh);
   254→      shard.setPosition(cx, cy).setRotation(angle);
   255→      scene.tweens.add({
   256→        targets: shard,
   257→        x: cx + Math.cos(angle) * speed, y: cy + Math.sin(angle) * speed,
   258→        alpha: 0, rotation: angle + Phaser.Math.FloatBetween(-1, 1),
   259→        duration: Phaser.Math.Between(270, 440), ease: 'Quad.easeOut',
   260→        onComplete: () => { shard.destroy(); },
   261→      });
   262→    }
   263→
   264→    // ─ 화면 전체 불꽃 폭발 (20개) ────────────────────────────────
   265→    const BURST_COLS = [0xff2200, 0xff6600, 0xffaa00, 0xffdd00, 0xffff88];
   266→    for (let i = 0; i < 20; i++) {
   267→      const gfx = scene.add.graphics();
   268→      const w   = Phaser.Math.Between(4, 10);
   269→      const h   = Phaser.Math.Between(10, 22);
   270→      const col = Phaser.Utils.Array.GetRandom(BURST_COLS) as number;
   271→
   272→      gfx.fillStyle(col, Phaser.Math.FloatBetween(0.22, 0.50));
   273→      gfx.fillPoints(LegacyAbility.flamePts(w, h), true);
   274→      gfx.fillStyle(0xffee88, Phaser.Math.FloatBetween(0.28, 0.55));
   275→      gfx.fillPoints(LegacyAbility.flamePts(w * 0.4, h * 0.5), true);
   276→
   277→      gfx.setPosition(Phaser.Math.Between(20, 380), Phaser.Math.Between(40, 560));
   278→      gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(-180, 180)));
   279→      gfx.setDepth(158).setAlpha(0);
   280→
   281→      scene.tweens.add({
   282→        targets: gfx, alpha: 1,
   283→        scaleX: Phaser.Math.FloatBetween(1.2, 1.9),
   284→        scaleY: Phaser.Math.FloatBetween(1.2, 1.9),
   285→        duration: 140, delay: Phaser.Math.Between(0, 280), ease: 'Quad.easeOut',
   286→        onComplete: () => {
   287→          scene.tweens.add({
   288→            targets: gfx, alpha: 0, y: gfx.y - Phaser.Math.Between(20, 50),
   289→            duration: Phaser.Math.Between(380, 650), ease: 'Quad.easeIn',
   290→            onComplete: () => { gfx.destroy(); },
   291→          });
   292→        },
   293→      });
   294→    }
   295→
   296→    // ─ 상단 노란빛 그라데이션 ────────────────────────────────────
   297→    this.legacyTopGlow = scene.add.graphics();
   298→    this.legacyTopGlow.fillGradientStyle(0xffee00, 0xffee00, 0xffee00, 0xffee00, 0.28, 0.28, 0, 0);
   299→    this.legacyTopGlow.fillRect(0, 0, 400, 220);
   300→    this.legacyTopGlow.setDepth(148);
   301→
   302→    this.legacyPulseTween = scene.tweens.add({
   303→      targets: [this.legacyTopGlow], alpha: 0.55,
   304→      duration: 600, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
   305→    });
   306→
   307→    // ─ 레거시 모드 황금 빗줄기 (repeat: -1, 10초 후 remove로 정리) ─
   308→    this.legacyRainTimer = scene.time.addEvent({
   309→      delay: 120,
   310→      repeat: -1,
   311→      callback: () => { this.spawnRainStar(scene, LegacyAbility.RAIN_COLS_LEGACY, 0.75, 1.00, 3); },
   312→    });
   313→
   314→    // 레거시 모드 종료
   315→    const legacyDur = LegacyAbility.LEGACY_DURATION[this.awakeningLevel] ?? 15000;
   316→    scene.time.delayedCall(legacyDur, () => {
   317→      this.legacyModeActive = false;
   318→      this.legacyRainTimer?.remove();
   319→      this.legacyRainTimer = undefined;
   320→      this.legacyPulseTween?.stop();
   321→      this.legacyPulseTween = undefined;
   322→      scene.tweens.add({
   323→        targets: [this.legacyTopGlow], alpha: 0, duration: 400, ease: 'Quad.easeOut',
   324→        onComplete: () => {
   325→          this.legacyTopGlow?.destroy();
   326→          this.legacyTopGlow = undefined;
   327→        },
   328→      });
   329→
   330→      // ★3: 3초 미니 피버 / ★5: 5초
   331→      if (this.awakeningLevel >= 3) {
   332→        this.startFeverActive = true;
   333→        scene.time.delayedCall(this.awakeningLevel >= 5 ? 5000 : 3000, () => {
   334→          this.startFeverActive = false;
   335→        });
   336→      }
   337→    });
   338→  }
   339→
   340→  // ─────────────────────────────────────────────────────────────────
   341→  // D: 황금 빗줄기
   342→  // ─────────────────────────────────────────────────────────────────
   343→
   344→  private startFeverRain(api: GameSceneAPI): void {
   345→    const scene  = api.scene;
   346→    const feverDur = LegacyAbility.FEVER_DURATION[this.awakeningLevel] ?? 12000;
   347→    const REPEAT = Math.floor(feverDur / 140) - 1;
   348→
   349→    scene.time.addEvent({
   350→      delay: 140,
   351→      repeat: REPEAT,
   352→      callback: () => { this.spawnRainStar(scene, LegacyAbility.RAIN_COLS_FEVER, 0.60, 0.90, 2); },
   353→    });
   354→  }
   355→
   356→  /** 빗줄기 별 1개 생성 — startFeverRain / legacyRainTimer 공용 */
   357→  private spawnRainStar(
   358→    scene: Phaser.Scene,
   359→    cols: readonly number[],
   360→    aMin: number,
   361→    aMax: number,
   362→    count: number,
   363→  ): void {
   364→    for (let i = 0; i < count; i++) {
   365→      const gfx = scene.add.graphics();
