   370→      gfx.fillPoints(LegacyAbility.starPts(s), true);
   371→      gfx.fillStyle(0xffffff, aMax > 0.85 ? 0.65 : 0.50); // 레거시 모드는 하이라이트도 강하게
   372→      gfx.fillCircle(0, 0, s * 0.32);
   373→
   374→      gfx.setPosition(Phaser.Math.Between(10, 390), -15);
   375→      gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(0, 360)));
   376→      gfx.setDepth(85);
   377→
   378→      scene.tweens.add({
   379→        targets:  gfx,
   380→        y:        gfx.y + Phaser.Math.Between(450, 600),
   381→        x:        gfx.x + Phaser.Math.Between(-25, 25),
   382→        rotation: gfx.rotation + Phaser.Math.FloatBetween(1.5, 3.0),
   383→        alpha:    0,
   384→        duration: Phaser.Math.Between(2200, 3600),
   385→        ease:     'Linear',
   386→        onComplete: () => { gfx.destroy(); },
