   446→      gfx.fillStyle(0xff4400, 0.48); gfx.fillPoints(LegacyAbility.flamePts(w * 0.70, h * 0.76), true);
   447→      gfx.fillStyle(0xffcc00, 0.68); gfx.fillPoints(LegacyAbility.flamePts(w * 0.40, h * 0.50), true);
   448→
   449→      gfx.setPosition(
