import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI, SpecialPoopType } from './types';

/**
 * 광부 (SR) — 무지개똥 + 수집 보너스
 * ★0: +10점 / 200점마다  / ★1: +12점 / 180점마다
 * ★2: +15점 / 160점마다  / ★3: +20점 / 140점마다 + 무지개 수집 시 3초 자석
 */
export class MinerAbility extends BaseAbility {
  private lastRainbowScore = 0;
  private magnetActive = false;
  private magnetEndTime = 0;

  private static readonly BONUS    = [10, 12, 15, 20, 25, 30] as const;
  private static readonly INTERVAL = [200, 180, 160, 140, 120, 100] as const;
  private static readonly MAGNET_SPEED = 180;

  override onCollectSpecial(type: SpecialPoopType): number {
    const bonus = MinerAbility.BONUS[this.awakeningLevel] ?? 20;
    if (this.awakeningLevel >= 3 && type === 'rainbow') {
      this.magnetActive  = true;
      this.magnetEndTime = Date.now() + 3000;
    }
    return bonus;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    const interval = MinerAbility.INTERVAL[this.awakeningLevel] ?? 140;
    if (score % interval === 0 && score > this.lastRainbowScore) {
      this.lastRainbowScore = score;
      api.spawnRainbowPoop();
    }
  }

  /** 자석 효과: 특수 똥을 플레이어 쪽으로 끌어당김 */
  override onUpdate(api: GameSceneAPI): void {
    if (!this.magnetActive) return;
    if (Date.now() >= this.magnetEndTime) {
      this.magnetActive = false;
      return;
    }
    const px  = api.player.x;
    const py  = api.player.y;
    const spd = MinerAbility.MAGNET_SPEED;

    // ★5: 일반 똥도 자석에 포함
    const allSpecial = [
      ...api.goldPoops.getChildren(),
      ...api.diamondPoops.getChildren(),
      ...api.topazPoops.getChildren(),
      ...api.rainbowPoops.getChildren(),
      ...(this.awakeningLevel >= 5 ? api.poops.getChildren() : []),
    ] as Phaser.Physics.Arcade.Sprite[];

    for (const poop of allSpecial) {
      if (!poop.active) continue;
      const dx   = px - poop.x;
      const dy   = py - poop.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < 5) continue;
      (poop.body as Phaser.Physics.Arcade.Body).setVelocity(
        (dx / dist) * spd,
        (dy / dist) * spd,
      );
    }
  }
}

