    // console.log('[다이아똥] spawnDiamondPoop 메서드 호출됨');
    if (this.gameOver) {
      // console.log('[다이아똥] 게임 오버 상태라 생성 안 함');
      return;
    }

    // 다이아똥 1개를 화면 중앙 상단에서 생성 (더 잘 보이도록)
