import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 글리치 (SR) — 분신 소환 + 픽셀 박스 노이즈
 * 분신: 플레이어를 ~0.3초 딜레이로 따라다니며 특수 똥 수집
 * 200점마다: 검정 배경 + 네온 픽셀 박스 25개 생성 (일반 똥과 닿으면 둘 다 소멸)
 */
export class GlitchAbility extends BaseAbility {
  private ghost?: Phaser.Physics.Arcade.Sprite;
  private posHistory: Array<{ x: number; y: number }> = [];
  private readonly TRAIL_FRAMES = 18; // ~0.3초 딜레이 (60fps 기준)
  private noiseGroup!: Phaser.Physics.Arcade.Group;

  override onCreate(api: GameSceneAPI): void {
    if (!api.isClassicMode) return;

    // 분신 생성
    this.ghost = api.scene.physics.add.sprite(api.player.x, api.player.y, 'glitch_front');
    this.ghost.setDisplaySize(60, 80).setAlpha(0.45).setDepth(5);
    (this.ghost.body as Phaser.Physics.Arcade.Body).setAllowGravity(false);

    const makeCollect = (
      collectFn: (p: Phaser.Physics.Arcade.Sprite) => void,
    ): Phaser.Types.Physics.Arcade.ArcadePhysicsCallback =>
      (_, p) => {
        const sp = p as Phaser.Physics.Arcade.Sprite;
        if (!sp.active) return;
        collectFn(sp);
      };
    api.scene.physics.add.overlap(this.ghost, api.goldPoops,    makeCollect(p => api.collectGoldPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.diamondPoops, makeCollect(p => api.collectDiamondPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.topazPoops,   makeCollect(p => api.collectTopazPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.rainbowPoops, makeCollect(p => api.collectRainbowPoop(p)));

    // 히트박스용 1×1 투명 픽셀 텍스처
    if (!api.scene.textures.exists('noise_pixel')) {
      const g = api.scene.make.graphics({ x: 0, y: 0 });
      g.fillStyle(0xffffff);
      g.fillRect(0, 0, 1, 1);
      g.generateTexture('noise_pixel', 1, 1);
      g.destroy();
    }

    // 노이즈 블록 히트박스 그룹 (시각 요소는 Graphics로 별도 처리)
    this.noiseGroup = api.scene.physics.add.group({ allowGravity: false });

    // 노이즈 블록 ↔ 일반 똥: 둘 다 소멸, 연결된 Graphics도 함께 제거
    api.scene.physics.add.overlap(
      this.noiseGroup,
      api.poops,
      (block, poop) => {
        const b = block as Phaser.Physics.Arcade.Sprite;
        (b.getData('gfx') as Phaser.GameObjects.Graphics | undefined)?.destroy();
        (b.getData('tween') as Phaser.Tweens.Tween | undefined)?.stop();
        b.destroy();
        (poop as Phaser.Physics.Arcade.Sprite).destroy();
      },
    );
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (!api.isClassicMode) return;
    if (score % 200 === 0) {
      this.spawnNoisePixelBurst(api);
    }
  }

  override onUpdate(api: GameSceneAPI): void {
    if (!this.ghost || !api.isClassicMode) return;
    this.posHistory.push({ x: api.player.x, y: api.player.y });
    if (this.posHistory.length > this.TRAIL_FRAMES) {
      const target = this.posHistory.shift()!;
      this.ghost.x = target.x;
      this.ghost.y = target.y;
    } else {
      this.ghost.x = api.player.x;
      this.ghost.y = api.player.y;
    }
  }

  private spawnNoisePixelBurst(api: GameSceneAPI): void {
    const cam = api.scene.cameras.main;
    const NEON_PINK  = 0xff00ff;
    const NEON_GREEN = 0x00ff41;

    for (let i = 0; i < 25; i++) {
      const x = Phaser.Math.Between(20, cam.width  - 20);
      const y = Phaser.Math.Between(60, cam.height - 60);
      const w = Phaser.Math.Between(10, 22);
      const h = Phaser.Math.Between(10, 22);
      const neon = Math.random() < 0.5 ? NEON_PINK : NEON_GREEN;

      // 시각: 검정 채움 + 네온 테두리 (픽셀 박스)
      const gfx = api.scene.add.graphics();
      gfx.setDepth(50);
      const drawBox = (alpha: number) => {
        gfx.clear();
        gfx.fillStyle(0x000000, alpha);
        gfx.fillRect(x - w / 2, y - h / 2, w, h);
        gfx.lineStyle(2, neon, alpha);
        gfx.strokeRect(x - w / 2, y - h / 2, w, h);
      };
      drawBox(1);

      // 깜빡임: Graphics 직접 알파 트윈
      const tween = api.scene.tweens.add({
        targets: gfx,
        alpha: { from: 1, to: 0.15 },
        duration: Phaser.Math.Between(60, 130),
        yoyo: true,
        repeat: -1,
      });

      // 히트박스: 투명 physics 스프라이트, Graphics와 연결
      const body = this.noiseGroup.create(x, y, 'noise_pixel') as Phaser.Physics.Arcade.Sprite;
      body.setDisplaySize(w, h).setAlpha(0);
      (body.body as Phaser.Physics.Arcade.Body)
        .setSize(w, h)
        .setAllowGravity(false)
        .setVelocity(0, 0);
      body.setData('gfx', gfx);
      body.setData('tween', tween);
    }
  }
}

