        for (let py = y - h / 2; py < y + h / 2; py += PIXEL_SIZE) {
          if (Math.random() > 0.4) {
            const c = LCD_COLORS[Phaser.Math.Between(0, LCD_COLORS.length - 1)];
            gfx.fillStyle(c, 1);
            gfx.fillRect(px, py, PIXEL_SIZE, PIXEL_SIZE);
          }
        }
      }

      // 깜빡임
      const tween = api.scene.tweens.add({
        targets: gfx,
        alpha: { from: 1, to: 0.1 },
        duration: Phaser.Math.Between(60, 130),
        yoyo: true,
        repeat: -1,
      });

      // 투명 physics 히트박스 (Graphics와 연결)
      const body = this.noiseGroup.create(x, y, 'noise_pixel') as Phaser.Physics.Arcade.Sprite;
      body.setDisplaySize(w, h).setAlpha(0);
      (body.body as Phaser.Physics.Arcade.Body)
        .setSize(w, h)
        .setAllowGravity(false)
        .setVelocity(0, 0);
      body.setData('gfx', gfx);
      body.setData('tween', tween);

      // 0.5초 후 자동 소멸 (일반 똥에 먼저 닿으면 즉시 소멸)
      api.scene.time.delayedCall(500, () => {
        if (body.active) {
          tween.stop();
          gfx.destroy();
          body.destroy();
        }
      });
    }
  }
}

