     1→import { BaseAbility } from './BaseAbility';
     2→import type { GameSceneAPI } from './types';
     3→
     4→/**
     5→ * 레거시 (UR) — 피버 + 레거시 모드
     6→ * ★0: 6초 피버 / 불태우기 30%/2개(일반) 60%/4개(레거시) / 500점마다 / 10초 / 1.2배
     7→ * ★1: 8초 / 35%/2개 65%/4개 / 450점마다 / 10초 / 1.25배
     8→ * ★2: 10초 / 40%/3개 70%/4개 / 400점마다 / 12초 / 1.30배
     9→ * ★3: 12초 / 45%/3개 75%/4개 / 350점마다 / 15초 / 1.35배 + 모드 종료 직후 3초 미니 피버
    10→ */
    11→export class LegacyAbility extends BaseAbility {
    12→  private startFeverActive = false;
    13→  private legacyModeActive = false;
    14→  private accum           = 0;
    15→  private lastLegacyScore = 0;
    16→
    17→  private static readonly FEVER_DURATION  = 6000;
    18→  private static readonly LEGACY_INTERVAL = 500;
    19→  private static readonly LEGACY_DURATION = 10000;
    20→  private static readonly SCORE_EXTRA     = 0.20;
    21→  private static readonly BURN_CHANCE_N   = 0.30;
    22→  private static readonly BURN_CHANCE_L   = 0.60;
    23→  private static readonly BURN_COUNT_N    = 2;
    24→  private static readonly BURN_COUNT_L    = 4;
    25→  private legacyTopGlow?:    Phaser.GameObjects.Graphics;
    26→  private legacyPulseTween?: Phaser.Tweens.Tween;
    27→  private legacyRainTimer?:  Phaser.Time.TimerEvent;
    28→
    29→  // A: 상시 불꽃 오라
    30→  private oraTimer = 0;
    31→  private static readonly ORA_INTERVAL_NORMAL = 180; // ms
    32→  private static readonly ORA_INTERVAL_LEGACY =  80; // ms
    33→  private static readonly ORA_COLS_NORMAL = [0xff3300, 0xff6600, 0xffaa00];
    34→  private static readonly ORA_COLS_LEGACY = [0xffaa00, 0xffcc00, 0xffee44, 0xffffff];
    35→
    36→  // D: 빗줄기 색상
    37→  private static readonly RAIN_COLS_FEVER  = [0xff8800, 0xffaa00, 0xffcc00, 0xffee00];
    38→  private static readonly RAIN_COLS_LEGACY = [0xff5500, 0xff8800, 0xffaa00, 0xffcc00];
    39→
    40→  // ── 불꽃 물방울 다각형 좌표 ─────────────────────────────────────────
    41→  private static flamePts(w: number, h: number) {
    42→    return [
    43→      { x:  0,         y: -h        },
    44→      { x:  w * 0.55,  y: -h * 0.1  },
    45→      { x:  w * 0.75,  y:  h * 0.35 },
    46→      { x:  w * 0.3,   y:  h        },
    47→      { x: -w * 0.3,   y:  h        },
    48→      { x: -w * 0.75,  y:  h * 0.35 },
    49→      { x: -w * 0.55,  y: -h * 0.1  },
    50→    ];
    51→  }
    52→
    53→  // ── 8각 별 좌표 (빗줄기 공용) ────────────────────────────────────────
    54→  private static starPts(s: number) {
    55→    return [
    56→      { x:  0,       y: -s       }, { x:  s * 0.4, y: -s * 0.4 },
    57→      { x:  s,       y:  0       }, { x:  s * 0.4, y:  s * 0.4 },
    58→      { x:  0,       y:  s       }, { x: -s * 0.4, y:  s * 0.4 },
    59→      { x: -s,       y:  0       }, { x: -s * 0.4, y: -s * 0.4 },
    60→    ];
    61→  }
    62→
    63→  // ─────────────────────────────────────────────────────────────────
    64→  // 생명주기
    65→  // ─────────────────────────────────────────────────────────────────
    66→
    67→  override onCreate(api: GameSceneAPI): void {
    68→    this.startFeverActive = true;
    69→    this.startFeverRain(api);
    70→    api.scene.time.delayedCall(LegacyAbility.FEVER_DURATION, () => {
    71→      this.startFeverActive = false;
    72→    });
    73→  }
    74→
    75→  override onUpdate(api: GameSceneAPI): void {
    76→    const delta = api.scene.game.loop.delta;
    77→    this.oraTimer += delta;
    78→    const interval = this.legacyModeActive
    79→      ? LegacyAbility.ORA_INTERVAL_LEGACY
    80→      : LegacyAbility.ORA_INTERVAL_NORMAL;
    81→    if (this.oraTimer >= interval) {
    82→      this.oraTimer -= interval;
    83→      this.spawnOraFlame(api);
    84→    }
    85→  }
    86→
    87→  override getTickScore(base: number): number {
    88→    if (!this.legacyModeActive) return base;
    89→    const extra = LegacyAbility.SCORE_EXTRA;
    90→    this.accum += base * extra;
    91→    const bonus = Math.floor(this.accum);
    92→    this.accum -= bonus;
    93→    return base + bonus;
    94→  }
    95→
    96→  override overrideSpawnPoop(api: GameSceneAPI): boolean {
    97→    if (this.startFeverActive) {
    98→      api.spawnGoldPoop();
    99→      api.spawnGoldPoop();
   100→      return true;
   101→    }
   102→    return false;
   103→  }
   104→
   105→  override onAfterSpawnPoop(api: GameSceneAPI): void {
   106→    const chance = this.legacyModeActive ? LegacyAbility.BURN_CHANCE_L : LegacyAbility.BURN_CHANCE_N;
   107→    const count  = this.legacyModeActive ? LegacyAbility.BURN_COUNT_L  : LegacyAbility.BURN_COUNT_N;
   108→    if (Math.random() < chance) {
   109→      this.burnRandomPoops(api, count);
   110→    }
   111→  }
   112→
   113→  override onScoreMilestone(score: number, api: GameSceneAPI): void {
   114→    const interval = LegacyAbility.LEGACY_INTERVAL;
   115→    if (score % interval === 0 && score > this.lastLegacyScore) {
   116→      this.lastLegacyScore = score;
   117→      this.activateLegacyMode(api);
   118→    }
   119→  }
   120→
   121→  // ─────────────────────────────────────────────────────────────────
   122→  // A: 상시 불꽃 오라
   123→  // ─────────────────────────────────────────────────────────────────
   124→
   125→  private spawnOraFlame(api: GameSceneAPI): void {
   126→    const scene = api.scene;
   127→    const px    = api.player.x;
   128→    const py    = api.player.y;
   129→    const leg   = this.legacyModeActive;
   130→    const cols  = leg ? LegacyAbility.ORA_COLS_LEGACY : LegacyAbility.ORA_COLS_NORMAL;
   131→    const count = leg ? Phaser.Math.Between(5, 7) : Phaser.Math.Between(2, 3);
   132→    const rMax  = leg ? 2.2  : 1.6;
   133→    const aMax  = leg ? 0.90 : 0.70;
   134→    const riseMin = leg ? 20  : 14;
   135→    const riseMax = leg ? 42  : 28;
   136→    const lifeMin = leg ? 280 : 180;
   137→    const lifeMax = leg ? 520 : 380;
   138→
   139→    for (let i = 0; i < count; i++) {
   140→      const gfx = scene.add.graphics();
   141→      const r   = Phaser.Math.FloatBetween(0.8, rMax);
   142→      const col = Phaser.Utils.Array.GetRandom(cols) as number;
   143→      const a   = Phaser.Math.FloatBetween(0.50, aMax);
   144→
   145→      gfx.fillStyle(col, a);
   146→      gfx.fillCircle(0, 0, r);
   147→      gfx.setPosition(
   148→        px + Phaser.Math.Between(-10, 10),
   149→        py + Phaser.Math.Between(10, 24),
   150→      );
   151→      gfx.setDepth(88);
   152→
   153→      scene.tweens.add({
   154→        targets:  gfx,
   155→        y:        gfx.y - Phaser.Math.Between(riseMin, riseMax),
   156→        x:        gfx.x + Phaser.Math.Between(-4, 4),
   157→        alpha:    0,
   158→        scaleX:   0.15,
   159→        scaleY:   0.15,
   160→        duration: Phaser.Math.Between(lifeMin, lifeMax),
   161→        ease:     'Quad.easeOut',
   162→        onComplete: () => { gfx.destroy(); },
   163→      });
   164→    }
   165→  }
   166→
   167→  // ─────────────────────────────────────────────────────────────────
   168→  // B: 화염 추적선
   169→  // ─────────────────────────────────────────────────────────────────
   170→
   171→  private drawFireTrail(
   172→    scene: Phaser.Scene,
   173→    fromX: number, fromY: number,
   174→    toList: { x: number; y: number }[],
   175→  ): void {
   176→    if (toList.length === 0) return;
   177→
   178→    const gfx = scene.add.graphics();
   179→    gfx.setDepth(195);
   180→
   181→    for (const { x, y } of toList) {
   182→      gfx.lineStyle(3.5, 0xff6600, 0.50);
   183→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   184→      gfx.lineStyle(1.5, 0xffee00, 0.75);
   185→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   186→    }
   187→
   188→    scene.tweens.add({
   189→      targets: gfx, alpha: 0, duration: 200, ease: 'Quad.easeOut',
   190→      onComplete: () => { gfx.destroy(); },
   191→    });
   192→  }
   193→
   194→  // ─────────────────────────────────────────────────────────────────
   195→  // C: 레거시 모드 활성화
   196→  // ─────────────────────────────────────────────────────────────────
   197→
   198→  private activateLegacyMode(api: GameSceneAPI): void {
   199→    if (this.legacyModeActive) return;
   200→    this.legacyModeActive = true;
   201→    this.accum = 0;
   202→
   203→    const scene = api.scene;
   204→    const cx    = api.player.x;
   205→    const cy    = api.player.y;
   206→
   207→    // ─ 반투명 플래시 ──────────────────────────────────────────────
   208→    const flashOverlay = scene.add.graphics().setDepth(200);
   209→    flashOverlay.fillStyle(0xffee00, 1);
   210→    flashOverlay.fillRect(0, 0, 400, 600);
   211→    flashOverlay.setAlpha(0.38);
   212→    scene.tweens.add({
   213→      targets: flashOverlay, alpha: 0, duration: 220, ease: 'Quad.easeOut',
   214→      onComplete: () => { flashOverlay.destroy(); },
   215→    });
   216→
   217→    // ─ 팽창 링 2개 ───────────────────────────────────────────────
   218→    [{ delay: 0, maxScale: 4.3 }, { delay: 80, maxScale: 3.4 }].forEach(({ delay, maxScale }) => {
   219→      const ring = scene.add.graphics().setDepth(155);
   220→      ring.lineStyle(2.5, 0xffee00, 0.9);
   221→      ring.strokeEllipse(0, 0, 74, 98);
   222→      ring.setPosition(cx, cy);
   223→      scene.tweens.add({
   224→        targets: ring, scaleX: maxScale, scaleY: maxScale, alpha: 0,
   225→        duration: 500, delay, ease: 'Quad.easeOut',
   226→        onComplete: () => { ring.destroy(); },
   227→      });
   228→    });
   229→
   230→    // ─ 채움 타원 ─────────────────────────────────────────────────
   231→    const fill = scene.add.graphics().setDepth(154);
   232→    fill.fillStyle(0xffaa00, 0.28);
   233→    fill.fillEllipse(0, 0, 74, 98);
   234→    fill.setPosition(cx, cy);
   235→    scene.tweens.add({
   236→      targets: fill, alpha: 0, duration: 180, ease: 'Quad.easeOut',
   237→      onComplete: () => { fill.destroy(); },
   238→    });
   239→
   240→    // ─ 파편 8개 ──────────────────────────────────────────────────
   241→    for (let i = 0; i < 8; i++) {
   242→      const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
   243→      const speed = Phaser.Math.FloatBetween(40, 95);
   244→      const sw    = Phaser.Math.Between(5, 12);
   245→      const sh    = Phaser.Math.Between(2, 5);
   246→      const shard = scene.add.graphics().setDepth(156);
   247→      shard.fillStyle(0xffee00, 1);
   248→      shard.fillRect(-sw / 2, -sh / 2, sw, sh);
   249→      shard.setPosition(cx, cy).setRotation(angle);
   250→      scene.tweens.add({
   251→        targets: shard,
   252→        x: cx + Math.cos(angle) * speed, y: cy + Math.sin(angle) * speed,
   253→        alpha: 0, rotation: angle + Phaser.Math.FloatBetween(-1, 1),
   254→        duration: Phaser.Math.Between(270, 440), ease: 'Quad.easeOut',
   255→        onComplete: () => { shard.destroy(); },
   256→      });
   257→    }
   258→
   259→    // ─ 화면 전체 불꽃 폭발 (20개) ────────────────────────────────
   260→    const BURST_COLS = [0xff2200, 0xff6600, 0xffaa00, 0xffdd00, 0xffff88];
   261→    for (let i = 0; i < 20; i++) {
   262→      const gfx = scene.add.graphics();
   263→      const w   = Phaser.Math.Between(4, 10);
   264→      const h   = Phaser.Math.Between(10, 22);
   265→      const col = Phaser.Utils.Array.GetRandom(BURST_COLS) as number;
   266→
   267→      gfx.fillStyle(col, Phaser.Math.FloatBetween(0.22, 0.50));
   268→      gfx.fillPoints(LegacyAbility.flamePts(w, h), true);
   269→      gfx.fillStyle(0xffee88, Phaser.Math.FloatBetween(0.28, 0.55));
   270→      gfx.fillPoints(LegacyAbility.flamePts(w * 0.4, h * 0.5), true);
   271→
   272→      gfx.setPosition(Phaser.Math.Between(20, 380), Phaser.Math.Between(40, 560));
   273→      gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(-180, 180)));
   274→      gfx.setDepth(158).setAlpha(0);
   275→
   276→      scene.tweens.add({
   277→        targets: gfx, alpha: 1,
   278→        scaleX: Phaser.Math.FloatBetween(1.2, 1.9),
   279→        scaleY: Phaser.Math.FloatBetween(1.2, 1.9),
   280→        duration: 140, delay: Phaser.Math.Between(0, 280), ease: 'Quad.easeOut',
   281→        onComplete: () => {
   282→          scene.tweens.add({
   283→            targets: gfx, alpha: 0, y: gfx.y - Phaser.Math.Between(20, 50),
   284→            duration: Phaser.Math.Between(380, 650), ease: 'Quad.easeIn',
   285→            onComplete: () => { gfx.destroy(); },
   286→          });
   287→        },
   288→      });
   289→    }
   290→
   291→    // ─ 상단 노란빛 그라데이션 ────────────────────────────────────
   292→    this.legacyTopGlow = scene.add.graphics();
   293→    this.legacyTopGlow.fillGradientStyle(0xffee00, 0xffee00, 0xffee00, 0xffee00, 0.28, 0.28, 0, 0);
   294→    this.legacyTopGlow.fillRect(0, 0, 400, 220);
   295→    this.legacyTopGlow.setDepth(148);
   296→
   297→    this.legacyPulseTween = scene.tweens.add({
   298→      targets: [this.legacyTopGlow], alpha: 0.55,
   299→      duration: 600, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
   300→    });
   301→
   302→    // ─ 레거시 모드 황금 빗줄기 (repeat: -1, 10초 후 remove로 정리) ─
   303→    this.legacyRainTimer = scene.time.addEvent({
   304→      delay: 120,
   305→      repeat: -1,
   306→      callback: () => { this.spawnRainStar(scene, LegacyAbility.RAIN_COLS_LEGACY, 0.75, 1.00, 3); },
   307→    });
   308→
   309→    // 레거시 모드 종료
   310→    const legacyDur = LegacyAbility.LEGACY_DURATION;
   311→    scene.time.delayedCall(legacyDur, () => {
   312→      this.legacyModeActive = false;
   313→      this.legacyRainTimer?.remove();
   314→      this.legacyRainTimer = undefined;
   315→      this.legacyPulseTween?.stop();
   316→      this.legacyPulseTween = undefined;
   317→      scene.tweens.add({
   318→        targets: [this.legacyTopGlow], alpha: 0, duration: 400, ease: 'Quad.easeOut',
   319→        onComplete: () => {
   320→          this.legacyTopGlow?.destroy();
   321→          this.legacyTopGlow = undefined;
   322→        },
   323→      });
   324→
   325→    });
   326→  }
   327→
   328→  // ─────────────────────────────────────────────────────────────────
   329→  // D: 황금 빗줄기
   330→  // ─────────────────────────────────────────────────────────────────
   331→
   332→  private startFeverRain(api: GameSceneAPI): void {
   333→    const scene  = api.scene;
   334→    const REPEAT = Math.floor(LegacyAbility.FEVER_DURATION / 140) - 1;
   335→
   336→    scene.time.addEvent({
   337→      delay: 140,
   338→      repeat: REPEAT,
   339→      callback: () => { this.spawnRainStar(scene, LegacyAbility.RAIN_COLS_FEVER, 0.60, 0.90, 2); },
   340→    });
   341→  }
   342→
   343→  /** 빗줄기 별 1개 생성 — startFeverRain / legacyRainTimer 공용 */
   344→  private spawnRainStar(
   345→    scene: Phaser.Scene,
   346→    cols: readonly number[],
   347→    aMin: number,
   348→    aMax: number,
   349→    count: number,
   350→  ): void {
   351→    for (let i = 0; i < count; i++) {
   352→      const gfx = scene.add.graphics();
   353→      const s   = Phaser.Math.FloatBetween(2.5, 5.5);
   354→      const col = Phaser.Utils.Array.GetRandom(cols as number[]) as number;
   355→
   356→      gfx.fillStyle(col, Phaser.Math.FloatBetween(aMin, aMax));
   357→      gfx.fillPoints(LegacyAbility.starPts(s), true);
   358→      gfx.fillStyle(0xffffff, aMax > 0.85 ? 0.65 : 0.50); // 레거시 모드는 하이라이트도 강하게
   359→      gfx.fillCircle(0, 0, s * 0.32);
   360→
   361→      gfx.setPosition(Phaser.Math.Between(10, 390), -15);
   362→      gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(0, 360)));
   363→      gfx.setDepth(85);
   364→
   365→      scene.tweens.add({
   366→        targets:  gfx,
   367→        y:        gfx.y + Phaser.Math.Between(450, 600),
   368→        x:        gfx.x + Phaser.Math.Between(-25, 25),
   369→        rotation: gfx.rotation + Phaser.Math.FloatBetween(1.5, 3.0),
   370→        alpha:    0,
   371→        duration: Phaser.Math.Between(2200, 3600),
   372→        ease:     'Linear',
   373→        onComplete: () => { gfx.destroy(); },
   374→      });
   375→    }
   376→  }
   377→
   378→  // ─────────────────────────────────────────────────────────────────
   379→  // 불태우기 로직
   380→  // ─────────────────────────────────────────────────────────────────
   381→
   382→  private burnRandomPoops(api: GameSceneAPI, count: number): void {
   383→    const visible = api.poops.getChildren().filter(
   384→      c => c.active && (c as Phaser.Physics.Arcade.Sprite).y > -10,
   385→    ) as Phaser.Physics.Arcade.Sprite[];
   386→
   387→    if (visible.length === 0) return;
   388→
   389→    // Partial Fisher-Yates: count개만 앞으로 뽑아내고 나머지 순회 생략
   390→    const pool = visible.slice();
   391→    const take = Math.min(count, pool.length);
   392→    for (let i = 0; i < take; i++) {
   393→      const j = i + Math.floor(Math.random() * (pool.length - i));
   394→      [pool[i], pool[j]] = [pool[j], pool[i]];
   395→    }
   396→    const targets = pool.slice(0, take);
   397→
   398→    this.drawFireTrail(
   399→      api.scene,
   400→      api.player.x, api.player.y,
   401→      targets.map(p => ({ x: p.x, y: p.y })),
   402→    );
   403→
   404→    for (const poop of targets) {
   405→      if (!poop.active) continue;
   406→      this.playBurnEffect(api.scene, poop.x, poop.y);
   407→      poop.destroy();
   408→      api.updateScore(10);
   409→    }
   410→  }
