import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 글리치 (SR) — 분신 배회 + 비트 플립
 * 분신: 화면 전체를 사인파로 배회하며 특수 똥 수집
 * 비트 플립: 일반 똥 스폰 직후 각 15% 확률로 금똥으로 변이 + 글리치 이펙트
 */
export class GlitchAbility extends BaseAbility {
  private ghost?: Phaser.Physics.Arcade.Sprite;
  private ghostTime: number = 0;

  override onCreate(api: GameSceneAPI): void {
    if (!api.isClassicMode) return;

    // 분신 생성
    this.ghost = api.scene.physics.add.sprite(api.player.x, api.player.y, 'glitch_front');
    this.ghost.setDisplaySize(60, 80).setAlpha(0.45).setDepth(5);
    (this.ghost.body as Phaser.Physics.Arcade.Body).setAllowGravity(false);

    const makeCollect = (
      collectFn: (p: Phaser.Physics.Arcade.Sprite) => void,
    ): Phaser.Types.Physics.Arcade.ArcadePhysicsCallback =>
      (_, p) => {
        const sp = p as Phaser.Physics.Arcade.Sprite;
        if (!sp.active) return;
        collectFn(sp);
      };
    api.scene.physics.add.overlap(this.ghost, api.goldPoops,    makeCollect(p => api.collectGoldPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.diamondPoops, makeCollect(p => api.collectDiamondPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.topazPoops,   makeCollect(p => api.collectTopazPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.rainbowPoops, makeCollect(p => api.collectRainbowPoop(p)));
  }

  override onAfterSpawnPoop(api: GameSceneAPI): void {
    if (!api.isClassicMode) return;

    // 방금 스폰된 똥(y < 0)만 대상 — 아직 화면 안으로 진입 전
    const freshPoops = (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active && p.y < 0);

    for (const poop of freshPoops) {
      if (Math.random() < 0.15) {
        const px = poop.x;
        const py = poop.y;
        poop.destroy();
        this.playBitFlipEffect(api, px, py);
        api.spawnGoldPoop();
      }
    }
  }

  override onUpdate(api: GameSceneAPI): void {
    if (!this.ghost || !api.isClassicMode) return;
    this.ghostTime += 0.025;
    const cam = api.scene.cameras.main;
    this.ghost.x = cam.width / 2 + Math.sin(this.ghostTime) * (cam.width / 2 - 40);
    this.ghost.y = cam.height / 2 + Math.sin(this.ghostTime * 0.7) * (cam.height / 2 - 100);
  }

  private playBitFlipEffect(api: GameSceneAPI, cx: number, cy: number): void {
    const scene = api.scene;

    // 흰 플래시 사각형
    const flash = scene.add.graphics().setDepth(150);
    flash.fillStyle(0xffffff, 1);
    flash.fillRect(cx - 20, cy - 20, 40, 40);
    scene.tweens.add({
      targets: flash,
      alpha: 0,
      duration: 100,
      onComplete: () => flash.destroy(),
    });

    // 금색 + 흰색 픽셀 파편
    for (let i = 0; i < 7; i++) {
      const px = scene.add.graphics().setDepth(151);
      const size = Phaser.Math.Between(2, 5);
      const color = Math.random() < 0.6 ? 0xffd700 : 0xffffff;
      px.fillStyle(color, 1);
      px.fillRect(0, 0, size, size);
      px.setPosition(cx, cy);

      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const dist  = Phaser.Math.FloatBetween(15, 45);
      scene.tweens.add({
        targets: px,
        x: cx + Math.cos(angle) * dist,
        y: cy + Math.sin(angle) * dist,
        alpha: 0,
        duration: Phaser.Math.Between(150, 300),
        ease: 'Quad.easeOut',
        onComplete: () => px.destroy(),
      });
    }
  }
}

