import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 글리치 (SR) — 분신 소환 + 픽셀 박스 노이즈
 * 분신: 플레이어를 ~0.3초 딜레이로 따라다니며 특수 똥 수집
 * 200점마다: 검정 배경 + 네온 픽셀 박스 25개 생성 (일반 똥과 닿으면 둘 다 소멸)
 */
export class GlitchAbility extends BaseAbility {
  private ghost?: Phaser.Physics.Arcade.Sprite;
  private ghostTime: number = 0;
  private noiseGroup!: Phaser.Physics.Arcade.Group;

  override onCreate(api: GameSceneAPI): void {
    if (!api.isClassicMode) return;

    // 분신 생성
    this.ghost = api.scene.physics.add.sprite(api.player.x, api.player.y, 'glitch_front');
    this.ghost.setDisplaySize(60, 80).setAlpha(0.45).setDepth(5);
    (this.ghost.body as Phaser.Physics.Arcade.Body).setAllowGravity(false);

    const makeCollect = (
      collectFn: (p: Phaser.Physics.Arcade.Sprite) => void,
    ): Phaser.Types.Physics.Arcade.ArcadePhysicsCallback =>
      (_, p) => {
        const sp = p as Phaser.Physics.Arcade.Sprite;
        if (!sp.active) return;
        collectFn(sp);
      };
    api.scene.physics.add.overlap(this.ghost, api.goldPoops,    makeCollect(p => api.collectGoldPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.diamondPoops, makeCollect(p => api.collectDiamondPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.topazPoops,   makeCollect(p => api.collectTopazPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.rainbowPoops, makeCollect(p => api.collectRainbowPoop(p)));

    // 히트박스용 1×1 투명 픽셀 텍스처
    if (!api.scene.textures.exists('noise_pixel')) {
      const g = api.scene.make.graphics({ x: 0, y: 0 });
      g.fillStyle(0xffffff);
      g.fillRect(0, 0, 1, 1);
      g.generateTexture('noise_pixel', 1, 1);
      g.destroy();
    }

    // 노이즈 블록 히트박스 그룹 (시각 요소는 Graphics로 별도 처리)
    this.noiseGroup = api.scene.physics.add.group({ allowGravity: false });

    // 노이즈 블록 ↔ 일반 똥: 둘 다 소멸, 연결된 Graphics도 함께 제거
    api.scene.physics.add.overlap(
      this.noiseGroup,
      api.poops,
      (block, poop) => {
        const b = block as Phaser.Physics.Arcade.Sprite;
        (b.getData('gfx') as Phaser.GameObjects.Graphics | undefined)?.destroy();
        (b.getData('tween') as Phaser.Tweens.Tween | undefined)?.stop();
        b.destroy();
        (poop as Phaser.Physics.Arcade.Sprite).destroy();
      },
    );
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (!api.isClassicMode) return;
    if (score % 100 === 0) {
      this.spawnNoisePixelBurst(api);
    }
  }

  override onUpdate(api: GameSceneAPI): void {
    if (!this.ghost || !api.isClassicMode) return;
    this.ghostTime += 0.025;
    const cam = api.scene.cameras.main;
    this.ghost.x = cam.width / 2 + Math.sin(this.ghostTime) * (cam.width / 2 - 40);
    this.ghost.y = cam.height / 2 + Math.sin(this.ghostTime * 0.7) * (cam.height / 2 - 100);
  }

  private spawnNoisePixelBurst(api: GameSceneAPI): void {
    const cam = api.scene.cameras.main;
    // 부서진 LCD 액정처럼 보이는 서브픽셀 색상 팔레트
    const LCD_COLORS = [0xff0000, 0x00ff00, 0x0000ff, 0xffffff, 0xffff00, 0x00ffff, 0xff00ff];
    const PIXEL_SIZE = 3;

    for (let i = 0; i < 2; i++) {
      const w = Phaser.Math.Between(18, 32);
      const h = Phaser.Math.Between(14, 24);
      const x = Phaser.Math.Between(Math.ceil(w / 2) + 10, cam.width  - Math.ceil(w / 2) - 10);
      const y = Phaser.Math.Between(Math.ceil(h / 2) + 60, cam.height - Math.ceil(h / 2) - 10);

      const gfx = api.scene.add.graphics();
      gfx.setDepth(50);

      // 검정 배경
      gfx.fillStyle(0x000000, 1);
      gfx.fillRect(x - w / 2, y - h / 2, w, h);

      // 3×3 픽셀 단위로 랜덤 LCD 서브픽셀 채움 (~60% 확률로 색상 부여)
      for (let px = x - w / 2; px < x + w / 2; px += PIXEL_SIZE) {
        for (let py = y - h / 2; py < y + h / 2; py += PIXEL_SIZE) {
          if (Math.random() > 0.4) {
            const c = LCD_COLORS[Phaser.Math.Between(0, LCD_COLORS.length - 1)];
            gfx.fillStyle(c, 1);
            gfx.fillRect(px, py, PIXEL_SIZE, PIXEL_SIZE);
          }
        }
      }

      // 깜빡임
      const tween = api.scene.tweens.add({
        targets: gfx,
        alpha: { from: 1, to: 0.1 },
        duration: Phaser.Math.Between(60, 130),
        yoyo: true,
        repeat: -1,
      });

      // 투명 physics 히트박스 (Graphics와 연결)
      const body = this.noiseGroup.create(x, y, 'noise_pixel') as Phaser.Physics.Arcade.Sprite;
      body.setDisplaySize(w, h).setAlpha(0);
      (body.body as Phaser.Physics.Arcade.Body)
        .setSize(w, h)
        .setAllowGravity(false)
        .setVelocity(0, 0);
      body.setData('gfx', gfx);
      body.setData('tween', tween);

      // 0.5초 후 자동 소멸 (일반 똥에 먼저 닿으면 즉시 소멸)
      api.scene.time.delayedCall(500, () => {
        if (body.active) {
          tween.stop();
          gfx.destroy();
          body.destroy();
        }
      });
    }
  }
}

import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 글리치 (SR) — 분신 배회 + 비트 플립
 * 분신: 화면 전체를 사인파로 배회하며 특수 똥 수집
 * 비트 플립: 일반 똥 스폰 직후 각 15% 확률로 금똥으로 변이 + 글리치 이펙트
 */
export class GlitchAbility extends BaseAbility {
  private ghost?: Phaser.Physics.Arcade.Sprite;
  private ghostTime: number = 0;

  override onCreate(api: GameSceneAPI): void {
    if (!api.isClassicMode) return;

    // 분신 생성
    this.ghost = api.scene.physics.add.sprite(api.player.x, api.player.y, 'glitch_front');
    this.ghost.setDisplaySize(60, 80).setAlpha(0.45).setDepth(5);
    (this.ghost.body as Phaser.Physics.Arcade.Body).setAllowGravity(false);

    const makeCollect = (
      collectFn: (p: Phaser.Physics.Arcade.Sprite) => void,
    ): Phaser.Types.Physics.Arcade.ArcadePhysicsCallback =>
      (_, p) => {
        const sp = p as Phaser.Physics.Arcade.Sprite;
        if (!sp.active) return;
        collectFn(sp);
      };
    api.scene.physics.add.overlap(this.ghost, api.goldPoops,    makeCollect(p => api.collectGoldPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.diamondPoops, makeCollect(p => api.collectDiamondPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.topazPoops,   makeCollect(p => api.collectTopazPoop(p)));
    api.scene.physics.add.overlap(this.ghost, api.rainbowPoops, makeCollect(p => api.collectRainbowPoop(p)));
  }

  override onAfterSpawnPoop(api: GameSceneAPI): void {
    if (!api.isClassicMode) return;

    // 방금 스폰된 똥(y < 0)만 대상 — 아직 화면 안으로 진입 전
    const freshPoops = (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active && p.y < 0);

    for (const poop of freshPoops) {
      if (Math.random() < 0.15) {
        const px = poop.x;
        const py = poop.y;
        poop.destroy();
        this.playBitFlipEffect(api, px, py);
        api.spawnGoldPoop();
      }
    }
  }

  override onUpdate(api: GameSceneAPI): void {
    if (!this.ghost || !api.isClassicMode) return;
    this.ghostTime += 0.025;
    const cam = api.scene.cameras.main;
    this.ghost.x = cam.width / 2 + Math.sin(this.ghostTime) * (cam.width / 2 - 40);
    this.ghost.y = cam.height / 2 + Math.sin(this.ghostTime * 0.7) * (cam.height / 2 - 100);
  }

  private playBitFlipEffect(api: GameSceneAPI, cx: number, cy: number): void {
    const scene = api.scene;

    // 흰 플래시 사각형
    const flash = scene.add.graphics().setDepth(150);
    flash.fillStyle(0xffffff, 1);
    flash.fillRect(cx - 20, cy - 20, 40, 40);
    scene.tweens.add({
      targets: flash,
      alpha: 0,
      duration: 100,
      onComplete: () => flash.destroy(),
    });

    // 금색 + 흰색 픽셀 파편
    for (let i = 0; i < 7; i++) {
      const px = scene.add.graphics().setDepth(151);
      const size = Phaser.Math.Between(2, 5);
      const color = Math.random() < 0.6 ? 0xffd700 : 0xffffff;
      px.fillStyle(color, 1);
      px.fillRect(0, 0, size, size);
      px.setPosition(cx, cy);

      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const dist  = Phaser.Math.FloatBetween(15, 45);
      scene.tweens.add({
        targets: px,
        x: cx + Math.cos(angle) * dist,
        y: cy + Math.sin(angle) * dist,
        alpha: 0,
        duration: Phaser.Math.Between(150, 300),
        ease: 'Quad.easeOut',
        onComplete: () => px.destroy(),
      });
    }
  }
}

